-- 3. EMOTIONS ENCYCLOPEDIA (76 items)
INSERT INTO public.emotions_encyclopedia (id, emotion_key, arabic_name, category, intensity_level, definition, body_sensations, triggers, healthy_expressions, metadata)
VALUES ('20000000-0000-0000-0000-000000000001', 'hope', 'أمل', 'تطلعات / مستقبل / إيجابية', 2, 'الأمل هو شعور داخلي بالتفاؤل نحو مستقبل أفضل، حتى لو كان الحاضر صعب. هو شعلة صغيرة بتضيء الظلام، وتحفز الشخص للاستمرار.', '["تنفس أعمق وهادئ","شعور بالارتياح الداخلي","ارتخاء في العضلات","انفتاح في وضعية الجسد"]'::jsonb, '["رؤية بارقة أمل وسط الصعوبات","كلمات تشجيعية من شخص مقرّب","نجاحات صغيرة رغم العقبات","الإيمان بأن الغد سيكون أفضل","تجارب إيجابية في الماضي"]'::jsonb, '[]'::jsonb, '{"english_name":"Hope","type":"فرعي","primary_emotion":{"name":"الفرح","english_name":"Joy","branches":["أمل","رضا","امتنان","سعادة","بهجة","نشوة","راحة","تفاؤل"]},"origin_body_part":"الصدر والمنطقة العليا من المعدة"}'::jsonb)
ON CONFLICT (emotion_key) DO UPDATE SET arabic_name = EXCLUDED.arabic_name, category = EXCLUDED.category, definition = EXCLUDED.definition, body_sensations = EXCLUDED.body_sensations, triggers = EXCLUDED.triggers, healthy_expressions = EXCLUDED.healthy_expressions, metadata = EXCLUDED.metadata;
INSERT INTO public.emotions_encyclopedia (id, emotion_key, arabic_name, category, intensity_level, definition, body_sensations, triggers, healthy_expressions, metadata)
VALUES ('20000000-0000-0000-0000-000000000002', 'gratitude', 'امتنان', 'تقدير / ارتباط / إيجابية', 2, 'الامتنان هو شعور عميق بالتقدير تجاه موقف أو شخص أو نعمة، يصاحبه إدراك لقيمة ما تم منحه أو حدوثه.', '["دفء في القلب","استرخاء عضلي خفيف","ابتسامة تلقائية","اتساع في الصدر"]'::jsonb, '["تجربة عطاء غير متوقع من شخص آخر","تذكر النِعَم الحالية أو الماضية","النجاة من موقف صعب","التقدير من الآخرين","تأمل اللحظات الإيجابية في الحياة"]'::jsonb, '[]'::jsonb, '{"english_name":"Gratitude","type":"فرعي","primary_emotion":{"name":"الفرح","english_name":"Joy","branches":["أمل","رضا","امتنان","سعادة","بهجة","نشوة","راحة","تفاؤل"]},"origin_body_part":"القلب والصدر"}'::jsonb)
ON CONFLICT (emotion_key) DO UPDATE SET arabic_name = EXCLUDED.arabic_name, category = EXCLUDED.category, definition = EXCLUDED.definition, body_sensations = EXCLUDED.body_sensations, triggers = EXCLUDED.triggers, healthy_expressions = EXCLUDED.healthy_expressions, metadata = EXCLUDED.metadata;
INSERT INTO public.emotions_encyclopedia (id, emotion_key, arabic_name, category, intensity_level, definition, body_sensations, triggers, healthy_expressions, metadata)
VALUES ('20000000-0000-0000-0000-000000000003', 'love', 'حب', 'ارتباط / علاقة / إيجابية', 2, 'شعور عميق بالارتباط، الانجذاب، والرغبة بالإيقاع العاطفي والجسدي نحو شخص آخر، يشمل مراحل متعددة من الشغف إلى الأمان.', '["خفقان في القلب","تعرّق باليدين","احمرار خدود","إحساس بالفراشات في المعدة (vagus nerve)"]'::jsonb, '["النظرات المتبادلة","لمسة حميمة","قرب جسدي متكرر","تجارب مشتركة أو دعم متبادل","فترة معاشرة أو تعارف عميق"]'::jsonb, '[]'::jsonb, '{"english_name":"Love","type":"أساسي","origin_body_part":"القلب (شعور عام)، الجهاز العصبي المركزي (مناطق مكافأة)"}'::jsonb)
ON CONFLICT (emotion_key) DO UPDATE SET arabic_name = EXCLUDED.arabic_name, category = EXCLUDED.category, definition = EXCLUDED.definition, body_sensations = EXCLUDED.body_sensations, triggers = EXCLUDED.triggers, healthy_expressions = EXCLUDED.healthy_expressions, metadata = EXCLUDED.metadata;
INSERT INTO public.emotions_encyclopedia (id, emotion_key, arabic_name, category, intensity_level, definition, body_sensations, triggers, healthy_expressions, metadata)
VALUES ('20000000-0000-0000-0000-000000000004', 'joy', 'فرح', 'إيجابية / سعادة / مكافأة', 2, 'شعور قوي بالإيجابية، السرور الداخلي والرضا، غالبًا نتيجة لحُدوث شيء مرغوب أو تحقيق هدف.', '["ابتسامة وسيلان لعاب","خفقان مرتفع مؤقت في القلب","توسّع في العينين وتحريك عضلات الوجه","زيادة في الطاقة والنشاط العام"]'::jsonb, '["تحقيق هدف مهم","لقاء شخص محبوب","تجربة ممتعة أو مفاجئة","موسيقى تلامس القلب","احتفال أو حدث سعيد"]'::jsonb, '[]'::jsonb, '{"english_name":"Joy","type":"أساسي","origin_body_part":"الجهاز العصبي المركزي ومنطقة ما تحت المهاد"}'::jsonb)
ON CONFLICT (emotion_key) DO UPDATE SET arabic_name = EXCLUDED.arabic_name, category = EXCLUDED.category, definition = EXCLUDED.definition, body_sensations = EXCLUDED.body_sensations, triggers = EXCLUDED.triggers, healthy_expressions = EXCLUDED.healthy_expressions, metadata = EXCLUDED.metadata;
INSERT INTO public.emotions_encyclopedia (id, emotion_key, arabic_name, category, intensity_level, definition, body_sensations, triggers, healthy_expressions, metadata)
VALUES ('20000000-0000-0000-0000-000000000005', 'satisfaction', 'رضا', 'إيجابية / مكافأة / وضوح داخلي', 2, 'شعور بالاكتمال الداخلي والتصالح مع الواقع، ناتج عن إشباع حاجة أو تحقيق هدف أو تقبّل الوضع كما هو.', '["تنفس أبطأ وأكثر انتظامًا","شعور بدفء في الصدر","هدوء في العضلات","ابتسامة طبيعية"]'::jsonb, '["إنهاء مهمة مهمة أو تحقيق هدف","وجود توازن بين التوقعات والواقع","شعور بالقبول الذاتي","تقدير أو تقييم إيجابي لما قمت به","علاقة صحية ومستقرة"]'::jsonb, '[]'::jsonb, '{"english_name":"Satisfaction","type":"فرعي","primary_emotion":{"name":"فرح","english_name":"Joy","branches":["سعادة","نشوة","بهجة","تفاؤل","راحة","امتنان"]},"origin_body_part":"الجهاز العصبي المركزي وغدة تحت المهاد"}'::jsonb)
ON CONFLICT (emotion_key) DO UPDATE SET arabic_name = EXCLUDED.arabic_name, category = EXCLUDED.category, definition = EXCLUDED.definition, body_sensations = EXCLUDED.body_sensations, triggers = EXCLUDED.triggers, healthy_expressions = EXCLUDED.healthy_expressions, metadata = EXCLUDED.metadata;
INSERT INTO public.emotions_encyclopedia (id, emotion_key, arabic_name, category, intensity_level, definition, body_sensations, triggers, healthy_expressions, metadata)
VALUES ('20000000-0000-0000-0000-000000000006', 'optimism', 'تفاؤل', 'إيجابية / أمل / توقع مستقبل أفضل', 2, 'اتجاه ذهني يميل لتوقع نتائج إيجابية ومشاعر سطحية من الأمل تجاه المستقبل، بغض النظر عن الصعوبات الحالية.', '["انخفاض في مستويات الكورتيزول","تنفس أهدأ وأكثر انتظامًا","مزيج من الدوبامين والسيروتونين يدعم وظائف الجسم"]'::jsonb, '["ممارسة إعادة تأطير الأفكار السلبية (learned optimism)","تذكّر ٣ أمور جيدة في نهاية كل يوم","مشاركة تجربة ممتعة أو نجاح بسيط","تلقّي كلمات تشجيعية","تجارب سابقة ناجحة وكلتها خير"]'::jsonb, '[]'::jsonb, '{"english_name":"Optimism","type":"فرعي","primary_emotion":{"name":"أمل","english_name":"Hope","branches":["تفاؤل","ثقة","إيمان بالحياة"]},"origin_body_part":"القشرة الأمامية، الجهاز العصبي المركزي"}'::jsonb)
ON CONFLICT (emotion_key) DO UPDATE SET arabic_name = EXCLUDED.arabic_name, category = EXCLUDED.category, definition = EXCLUDED.definition, body_sensations = EXCLUDED.body_sensations, triggers = EXCLUDED.triggers, healthy_expressions = EXCLUDED.healthy_expressions, metadata = EXCLUDED.metadata;
INSERT INTO public.emotions_encyclopedia (id, emotion_key, arabic_name, category, intensity_level, definition, body_sensations, triggers, healthy_expressions, metadata)
VALUES ('20000000-0000-0000-0000-000000000007', 'trust', 'ثقة', 'ارتباط / أمان / إيجابية', 2, 'شعور الأمان والاعتماد على شخص أو موقف دون توقع الخيانة أو الأذى.', '["انخفاض في ضغط الدم وتسارع نبضات القلب في الأوقات العصيبة","تنفس أبطأ وأكثر عمقًا عند الاتصال بأشخاص موثوق بهم","استرخاء عضلي عام عند الشعور بالأمان","تأثير مهدئ بعد اللمس أو التواصل الجسدي"]'::jsonb, '["تجرِبة سابقة موثوقة ومُعزّزة للعلاقة","التواصل المفتوح والاحترام المتبادل","موقف دعم أو حماية من قبل الآخر","وعد تم الوفاء به مرارًا","إصدار إشارات غير لفظية للأمان (نظرات، صوت هادئ، لمسة)"]'::jsonb, '[]'::jsonb, '{"english_name":"Trust","type":"أساسي","primary_emotion":{"name":"الثقة","english_name":"Trust","branches":[]},"origin_body_part":"تفاعل محور hypothalamus–pituitary (HPA) مع الجهاز العصبي المركزي"}'::jsonb)
ON CONFLICT (emotion_key) DO UPDATE SET arabic_name = EXCLUDED.arabic_name, category = EXCLUDED.category, definition = EXCLUDED.definition, body_sensations = EXCLUDED.body_sensations, triggers = EXCLUDED.triggers, healthy_expressions = EXCLUDED.healthy_expressions, metadata = EXCLUDED.metadata;
INSERT INTO public.emotions_encyclopedia (id, emotion_key, arabic_name, category, intensity_level, definition, body_sensations, triggers, healthy_expressions, metadata)
VALUES ('20000000-0000-0000-0000-000000000008', 'enthusiasm', 'حماس', 'إيجابية / شعور محفز / نشاط نفسي', 2, 'شعور قوي بالطاقة والتحفيز الداخلي، يُرافقه تركيز وحيوية تجاه نشاط معين أو هدف معين.', '["طاقة زائدة وخفة في الحركة","تعزيز نشاط القلب والتنفس","استقامة في الجسد وابتسامة عريضة","ملامح وجه متفتّحة ونظرة مركّزة"]'::jsonb, '["البدء بمشروع أو نشاط تُحبّه","وجود جمهور مشجع أو تفاعل إيجابي","سماع موسيقى تحفيزية أو حضور فعالية","وصول خطوة من نجاح","تحدٍّ يثير أسلوبك أو مهارتك"]'::jsonb, '[]'::jsonb, '{"english_name":"Enthusiasm","type":"فرعي","primary_emotion":{"name":"فرح","english_name":"Joy","branches":["نشوة","حماس","سرور","تفاؤل","رضا"]},"origin_body_part":"الجهاز العصبي المركزي والعصبونات المحفزة VTA"}'::jsonb)
ON CONFLICT (emotion_key) DO UPDATE SET arabic_name = EXCLUDED.arabic_name, category = EXCLUDED.category, definition = EXCLUDED.definition, body_sensations = EXCLUDED.body_sensations, triggers = EXCLUDED.triggers, healthy_expressions = EXCLUDED.healthy_expressions, metadata = EXCLUDED.metadata;
INSERT INTO public.emotions_encyclopedia (id, emotion_key, arabic_name, category, intensity_level, definition, body_sensations, triggers, healthy_expressions, metadata)
VALUES ('20000000-0000-0000-0000-000000000009', 'pride', 'فخر', 'وعي ذاتي / اجتماعي / إيجابية', 2, 'شعور ذاتي–اجتماعي ينبع من تقدير الذات أو إنجاز مرتبط بالمعايير الخاصة أو الاجتماعية، يجمع بين المتعة والفخر بالهوية أو الإنجاز.', '["وضعية ممتدة للصدر والرقبة مرفوعة","ابتسامة أو تعبير وجهي بالرضا","زيادة طفيفة في معدل التنفس والقلب","لغة جسد مفتوحة تعكس الثقة"]'::jsonb, '["تحقيق إنجاز مهم","التقدير الاجتماعي أو الاعتراف العام","تحقيق هدف شخصي صعب","الارتقاء بالوضع الاجتماعي أو الوظيفي","تجاوز تحدٍ باجتهاد وجهد كبير"]'::jsonb, '[]'::jsonb, '{"english_name":"Pride","type":"فرعي","primary_emotion":{"name":"إيجابية","english_name":"Positive Emotion","branches":["فخر","سعادة","إنجاز","اعتزاز"]},"origin_body_part":"الجهاز العصبي المركزي – قشرة أمامية ومخيلة اجتماعية"}'::jsonb)
ON CONFLICT (emotion_key) DO UPDATE SET arabic_name = EXCLUDED.arabic_name, category = EXCLUDED.category, definition = EXCLUDED.definition, body_sensations = EXCLUDED.body_sensations, triggers = EXCLUDED.triggers, healthy_expressions = EXCLUDED.healthy_expressions, metadata = EXCLUDED.metadata;
INSERT INTO public.emotions_encyclopedia (id, emotion_key, arabic_name, category, intensity_level, definition, body_sensations, triggers, healthy_expressions, metadata)
VALUES ('20000000-0000-0000-0000-000000000010', 'curiosity', 'فضول', 'استكشاف / معرفة / إيجابية', 2, 'شعور داخلي يدفع الشخص للبحث عن معلومات جديدة أو استكشاف المجهول نتيجة فجوة معرفية أو حاجة نفسية للتعلم.', '["تنفس أعمق وأبطأ","استقامة خفيفة للجسم عند التركيز","حركات ترقب غير واعية (عينان مفتوحتان، انحناء للأمام)","إيقاع قلبي منتظم مع توقع المكافأة"]'::jsonb, '["وجود فجوة بين ما تعرفه وما تريد معرفته","مواجهة لغز أو سؤال غير محسوم","عرض تفاصيل جديدة غامضة أو غير مكتملة","تقديم تحدٍ ذهني يتناسب مع قدراتك","مشاركة قصة أو معلومة مثيرة للاهتمام"]'::jsonb, '[]'::jsonb, '{"english_name":"Curiosity","type":"فرعي","primary_emotion":{"name":"اهتمام / ترقب","english_name":"Anticipation","branches":["فضول","اهتمام","تشويق"]},"origin_body_part":"القشرة أمام الجبهية (PFC)، نظام المكافأة (VTA–nucleus accumbens)، hippocampus"}'::jsonb)
ON CONFLICT (emotion_key) DO UPDATE SET arabic_name = EXCLUDED.arabic_name, category = EXCLUDED.category, definition = EXCLUDED.definition, body_sensations = EXCLUDED.body_sensations, triggers = EXCLUDED.triggers, healthy_expressions = EXCLUDED.healthy_expressions, metadata = EXCLUDED.metadata;
INSERT INTO public.emotions_encyclopedia (id, emotion_key, arabic_name, category, intensity_level, definition, body_sensations, triggers, healthy_expressions, metadata)
VALUES ('20000000-0000-0000-0000-000000000011', 'surprise', 'دهشة', 'أساسي / استجابة فطرية / نبرة تحذير', 2, 'رد فعل سريع وفوري لحدث غير متوقع، قد يكون إيجابي أو سلبي أو محايد، يوقف السياق الحالي للانتباه ويركّز الذهن.', '["تجمّد للحظات (freeze)","بطء مؤقت في ضربات القلب مفاجئاً","ارتفاع في ضغط الدم","اتساع بؤبؤ العين","كشف عضلي مفاجئ – سيل في العينين واسترخاء الفك"]'::jsonb, '["حدث غير متوقع أو مفاجئ","صوت مفاجئ أو ضوء قوي","معلومة جديدة غير متوقعة","مطابقة خاطئة بين التوقع والحقيقة","انقطاع السياق العادي فجأة"]'::jsonb, '[]'::jsonb, '{"english_name":"Surprise","type":"أساسي","origin_body_part":"تنشيط تلقائي للجهاز العصبي المركزي – منبه فوري"}'::jsonb)
ON CONFLICT (emotion_key) DO UPDATE SET arabic_name = EXCLUDED.arabic_name, category = EXCLUDED.category, definition = EXCLUDED.definition, body_sensations = EXCLUDED.body_sensations, triggers = EXCLUDED.triggers, healthy_expressions = EXCLUDED.healthy_expressions, metadata = EXCLUDED.metadata;
INSERT INTO public.emotions_encyclopedia (id, emotion_key, arabic_name, category, intensity_level, definition, body_sensations, triggers, healthy_expressions, metadata)
VALUES ('20000000-0000-0000-0000-000000000012', 'awe-with-fear', 'رهبة', 'أساسي / مزيج دهشة وخوف', 2, 'شعور مركب يجمع بين الانبهار والاستجابة للتهديد تجاه شيء هائل أو مفاجئ يفوق قدرة الفهم، وقد يُثير الخوف بسبب القوة أو العظمة.', '["تجمّد أو توقف لحظي (freeze)","ارتجاف طفيف أو قشعريرة (goosebumps)","توسع مفاجئ في حدقة العين","ارتفاع سريع في ضغط الدم والتنفس","ارتخاء عضلي قبل الانطلاق للحركة"]'::jsonb, '["مشهد طبيعي هائل (جبال، عواصف، بحر هائج)","ظواهر فلكية غير مألوفة (كسوف، شفق قطبي)","أعمال فنية ضخمة أو فظيعة في قاعدتها","قوة بشرية خارقة كجيش ينزل فجأة","تفوق قوة غير متوقع في آخرين أو في الطبيعة"]'::jsonb, '[]'::jsonb, '{"english_name":"Awe with Fear","type":"فرعي","origin_body_part":"تفعيل الجهاز العصبي الودي ومركز الأميجدالا–HPA، وانخراط PFC"}'::jsonb)
ON CONFLICT (emotion_key) DO UPDATE SET arabic_name = EXCLUDED.arabic_name, category = EXCLUDED.category, definition = EXCLUDED.definition, body_sensations = EXCLUDED.body_sensations, triggers = EXCLUDED.triggers, healthy_expressions = EXCLUDED.healthy_expressions, metadata = EXCLUDED.metadata;
INSERT INTO public.emotions_encyclopedia (id, emotion_key, arabic_name, category, intensity_level, definition, body_sensations, triggers, healthy_expressions, metadata)
VALUES ('20000000-0000-0000-0000-000000000013', 'inner-peace', 'سلام داخلي', 'إيجابية / استقرار نفسي / توازن داخلي', 2, 'شعور مستدام بالهدوء الداخلي، الغياب شبه الكلي للقلق أو التوتر، وانسجام بين العقل والجسد بما يخلق حالة من التوازن النفسي.', '["انخفاض معدل ضربات القلب وتوسّع الأوعية الدموية","انخفاض ضغط الدم","تنفس بطيء وعميق","استرخاء عام في العضلات"]'::jsonb, '["ممارسة التأمل أو اليقظة الذهنية","المشي في الطبيعة أو وسط المساحات الخضراء","تنفس عميق ومنتظم","ممارسة اليوغا أو التاي تشي","الانفصال عن ضغوط الحياة والتركيز على اللحظة"]'::jsonb, '[]'::jsonb, '{"english_name":"Inner Peace","type":"فرعي","primary_emotion":{"name":"هدوء","english_name":"Calmness","branches":["سلام داخلي","طمأنينة","استرخاء","راحة"]},"origin_body_part":"الجهاز العصبي المركزي – محور جهاز الهضم، vagus nerve، والمهاد (hypothalamus)"}'::jsonb)
ON CONFLICT (emotion_key) DO UPDATE SET arabic_name = EXCLUDED.arabic_name, category = EXCLUDED.category, definition = EXCLUDED.definition, body_sensations = EXCLUDED.body_sensations, triggers = EXCLUDED.triggers, healthy_expressions = EXCLUDED.healthy_expressions, metadata = EXCLUDED.metadata;
INSERT INTO public.emotions_encyclopedia (id, emotion_key, arabic_name, category, intensity_level, definition, body_sensations, triggers, healthy_expressions, metadata)
VALUES ('20000000-0000-0000-0000-000000000014', 'relief', 'ارتياح', 'إيجابية / إزالة الضغط / توازن', 2, 'شعور إيجابي يحدث عند انتهاء مشكلة أو تهديد، أو عند تجنّب موقف سلبي مفاجئ، ويُرافقه استرخاء وتنفّس عميق.', '["تنهيدة عميقة (sigh of relief) كإشارة لإعادة التوازن :contentReference[oaicite:1]{index=1}","انخفاض ضغط الدم وتباطؤ معدل ضربات القلب :contentReference[oaicite:2]{index=2}","انبساط عضلي واضح وصوت مريح","تنفس أعمق وأكثر انتظامًا :contentReference[oaicite:3]{index=3}"]'::jsonb, '["انتهاء ظرف ضاغط أو مخيف","تجنّب حادث أو مشكلة","الحصول على نتيجة إيجابية بعد قلق","سماع خبر مريح بعد انتظار","إتمام مهمة صعبة بسلام"]'::jsonb, '[]'::jsonb, '{"english_name":"Relief","type":"فرعي","primary_emotion":{"name":"إيجابية","english_name":"Positive Emotion","branches":["ارتياح","راحة","طمأنينة"]},"origin_body_part":"الجهاز العصبي المركزي – استجابة parasympathetic"}'::jsonb)
ON CONFLICT (emotion_key) DO UPDATE SET arabic_name = EXCLUDED.arabic_name, category = EXCLUDED.category, definition = EXCLUDED.definition, body_sensations = EXCLUDED.body_sensations, triggers = EXCLUDED.triggers, healthy_expressions = EXCLUDED.healthy_expressions, metadata = EXCLUDED.metadata;
INSERT INTO public.emotions_encyclopedia (id, emotion_key, arabic_name, category, intensity_level, definition, body_sensations, triggers, healthy_expressions, metadata)
VALUES ('20000000-0000-0000-0000-000000000015', 'calmness', 'هدوء', 'إيجابية / توازن / استقرار نفسي', 2, 'حالة نفسية وجسدية تتميز بانخفاض التوتر، استرخاء الجسم والعقل، ووضوح داخلي دون صخب أو اضطراب.', '["انخفاض ضغط الدم ومعدل ضربات القلب :contentReference[oaicite:1]{index=1}","تنفس أبطأ وأكثر عمقًا :contentReference[oaicite:2]{index=2}","استرخاء عضلي عام وانخفاض التوتر :contentReference[oaicite:3]{index=3}","تحسن في معدل تباين ضربات القلب (HRV)"]'::jsonb, '["ممارسة التأمل أو اليقظة الذهنية","تنفس عميق ومنتظم","موسيقى هادئة أو أجواء صامتة","المشي في الطبيعة أو وسط مناظر هادئة","التوقف لحظة والتركيز على اللحظة الحاضرة"]'::jsonb, '[]'::jsonb, '{"english_name":"Calmness","type":"فرعي","origin_body_part":"الجهاز العصبي المركزي – مراكز التأمل (PFC، vagus nerve، hypothalamus)"}'::jsonb)
ON CONFLICT (emotion_key) DO UPDATE SET arabic_name = EXCLUDED.arabic_name, category = EXCLUDED.category, definition = EXCLUDED.definition, body_sensations = EXCLUDED.body_sensations, triggers = EXCLUDED.triggers, healthy_expressions = EXCLUDED.healthy_expressions, metadata = EXCLUDED.metadata;
INSERT INTO public.emotions_encyclopedia (id, emotion_key, arabic_name, category, intensity_level, definition, body_sensations, triggers, healthy_expressions, metadata)
VALUES ('20000000-0000-0000-0000-000000000016', 'empathy', 'تعاطف', 'اجتماعي / عاطفي / إيجابية', 2, 'قدرة الفرد على فهم مشاعر الآخرين ومشاركتها داخلًا، سواء أدرك ذلك أو اتأثر عاطفيًا، مدموجة بالإدراك المعرفي للحالة النفسية للآخر.', '["تسارع نبض أو تنفس عند الشعور بحزن الآخر","انقباض عضلات الوجه لتطابق تعبير الآخر","شعور بالتضامن الداخلي أو ألم مشترك"]'::jsonb, '["ملاحظة ألم أو حزن شخص آخر","أن تُعامل معاملة تكتشف فيها رغبة الآخر في الدعم","رؤية أحد يواجه تحديًا جسديًا أو نفسيًا","مشاركة قصة مؤثرة تساعدك تتخيل موقف الآخر","تواصل عاطفي واضح (نظرة، صوت، رسالة)"]'::jsonb, '[]'::jsonb, '{"english_name":"Empathy","type":"أساسي","origin_body_part":"محاكاة داخلية من خلال الشبكات العصبية المرآوية ونظام المكافأة الاجتماعي"}'::jsonb)
ON CONFLICT (emotion_key) DO UPDATE SET arabic_name = EXCLUDED.arabic_name, category = EXCLUDED.category, definition = EXCLUDED.definition, body_sensations = EXCLUDED.body_sensations, triggers = EXCLUDED.triggers, healthy_expressions = EXCLUDED.healthy_expressions, metadata = EXCLUDED.metadata;
INSERT INTO public.emotions_encyclopedia (id, emotion_key, arabic_name, category, intensity_level, definition, body_sensations, triggers, healthy_expressions, metadata)
VALUES ('20000000-0000-0000-0000-000000000017', 'understanding-perspective-taking-', 'تفهم', 'اجتماعي / عاطفي / معرفي', 2, 'قدرة الإنسان على إدراك مشاعر وإطار ذهن الآخرين، وتفسير سياقاتهم النفسية، دون بالضرورة مشاركة شعوريًا.', '["توجيه العينين وتعابير الوجه التي تعكس انتباهًا","وقف مؤقت أو إبطاء في الكلام للاستماع","نبرة صوت أكثر دقة وهدوء في المحادثة","وضعية جسمية مائلة للأمام تشير للتركيز"]'::jsonb, '["الاستماع بانتباه لشخص يعبر عن مشاعره","مشاهدة تعبيرات وجه أو لغة جسد الآخر","طرح أسئلة مفتوحة لفهم دوافع وآراء الطرف الآخر","قراءة نصوص تعبر عن حالات عاطفية مختلفة","التدرب على التقمص العقلي (Theory‑of‑Mind)"]'::jsonb, '[]'::jsonb, '{"english_name":"Understanding (Perspective-taking)","type":"فرعي","origin_body_part":"التنشيط في القشرة ما قبل الجبهية، TPJ، ACC، وinsula"}'::jsonb)
ON CONFLICT (emotion_key) DO UPDATE SET arabic_name = EXCLUDED.arabic_name, category = EXCLUDED.category, definition = EXCLUDED.definition, body_sensations = EXCLUDED.body_sensations, triggers = EXCLUDED.triggers, healthy_expressions = EXCLUDED.healthy_expressions, metadata = EXCLUDED.metadata;
INSERT INTO public.emotions_encyclopedia (id, emotion_key, arabic_name, category, intensity_level, definition, body_sensations, triggers, healthy_expressions, metadata)
VALUES ('20000000-0000-0000-0000-000000000018', 'understanding', 'فهم', 'اجتماعي / معرفي / تواصل', 2, 'القدرة على إدراك وتفسير مشاعر، دوافع، وأفكار الآخرين بدقة، عن طريق الدمج المعرفي والعاطفي دون الانغماس الكامل في شعورهم.', '["توجيه العينين وتركيز أنيق على المتحدّث","إبطاء في الكلام للاستماع","وضعية جسمية تميل للأمام بانتباه","هدوء صوتي يعكس تركيزًا وفهمًا"]'::jsonb, '["الاستماع النشط لشخص يشرح مشاعره","ملاحظة تعابير الوجه ولغة الجسد","طرح أسئلة استيضاحية توضح السياق","التخيل العقلي لمكان وموقف الآخر","قراءة أو سماع قصص تعكس تجارب نفسية"]'::jsonb, '[]'::jsonb, '{"english_name":"Understanding","type":"فرعي","origin_body_part":"القشرة الجبهية، TPJ، ACC، شبكات المرآة"}'::jsonb)
ON CONFLICT (emotion_key) DO UPDATE SET arabic_name = EXCLUDED.arabic_name, category = EXCLUDED.category, definition = EXCLUDED.definition, body_sensations = EXCLUDED.body_sensations, triggers = EXCLUDED.triggers, healthy_expressions = EXCLUDED.healthy_expressions, metadata = EXCLUDED.metadata;
INSERT INTO public.emotions_encyclopedia (id, emotion_key, arabic_name, category, intensity_level, definition, body_sensations, triggers, healthy_expressions, metadata)
VALUES ('20000000-0000-0000-0000-000000000019', 'attachment', 'ارتباط', 'اجتماعي / علاقة / أمان', 2, 'حالة عاطفية ونفسية تتكون من الثقة والأمان والتعلق بآخر يمكن الاعتماد عليه—شخص يُشبع الحاجة للعلاقة الجادة والاستقرار.', '["انخفاض في ضغط الدم وتسارع نبضات القلب عند التهديد","نسبة أعلى من استجابة القلب الهادئة (HRV)","دفء جسدي وشعور بالاطمئنان مع العناق واللمس","ارتخاء عام وانخفاض التقلص العضلي"]'::jsonb, '["حماية واهتمام موثوق من شخص آخر","مشاركة تجربة مؤثرة أو موقف داعم","لمسة أو اتصال جسدي طويل مثل الحضن","قيام الطرف الآخر بمساعدة مستمرة دون خيانة ثقة","الوجود المستمر بغض النظر عن الظروف"]'::jsonb, '[]'::jsonb, '{"english_name":"Attachment","type":"أساسي","origin_body_part":"محور HPA + الجهاز العصبي اللاودي + إفراز الأوكسيتوسين"}'::jsonb)
ON CONFLICT (emotion_key) DO UPDATE SET arabic_name = EXCLUDED.arabic_name, category = EXCLUDED.category, definition = EXCLUDED.definition, body_sensations = EXCLUDED.body_sensations, triggers = EXCLUDED.triggers, healthy_expressions = EXCLUDED.healthy_expressions, metadata = EXCLUDED.metadata;
INSERT INTO public.emotions_encyclopedia (id, emotion_key, arabic_name, category, intensity_level, definition, body_sensations, triggers, healthy_expressions, metadata)
VALUES ('20000000-0000-0000-0000-000000000020', 'belonging', 'انتماء', 'اجتماعي / عاطفي / أمان', 2, 'الشعور بأنك جزء من مجموعة تُقدرك وتُقبلك كما أنت، مما يخلق أمانًا نفسيًا وهويّة شعورية مشتركة.', '["استرخاء عضلي وضغط دم أقل عند الشعور بالقبول","زيادة تباين ضربات القلب (HRV)","استجابة جسمية داعمة – مثل حضن أو اتصال بصري","انخفاض استجابة التوتر عند الشعور بالتقبل"]'::jsonb, '["القبول والمشاركة الفعلية في مجموعة","دعم متبادل وإحساس بتقدير الآخر","التواصل المستمر والاحترام","مشاركة قيم أو اهتمامات مشتركة","تفاعل إيجابي ومستمر مع الآخرين"]'::jsonb, '[]'::jsonb, '{"english_name":"Belonging","type":"فرعي","origin_body_part":"إفراز الأكسيتوسين، نشاط vmPFC وACC، نظام المكافأة – الجهاز العصبي اللاإرادي"}'::jsonb)
ON CONFLICT (emotion_key) DO UPDATE SET arabic_name = EXCLUDED.arabic_name, category = EXCLUDED.category, definition = EXCLUDED.definition, body_sensations = EXCLUDED.body_sensations, triggers = EXCLUDED.triggers, healthy_expressions = EXCLUDED.healthy_expressions, metadata = EXCLUDED.metadata;
INSERT INTO public.emotions_encyclopedia (id, emotion_key, arabic_name, category, intensity_level, definition, body_sensations, triggers, healthy_expressions, metadata)
VALUES ('20000000-0000-0000-0000-000000000021', 'playfulness', 'روح اللعب', 'إيجابية / تفاعل اجتماعي / استكشاف', 2, 'ميل ذهني وشخصي لإعادة صياغة المواقف اليومية بطريقة مسلية، إيجابية ومليئة بالفضول والمرح، ممّا يعزز التفاعل والإبداع.', '["زيادة التنفس والطاقة الجسدية","حركة جسدية حرة (وجه، يد، جسد)","ضحك أو ابتسامة تلقائية","وترية عضلية مرنة ومنفتحة"]'::jsonb, '["وجود بيئة مسلية أو تفاعلية","مشاركة بألعاب أو نكات خفيفة","تشجيع على الابتكار وعدم الجدية","حالة أمان نفسي واجتماعي","ذكريات طفولية أو لحظات ضحك مشتركة"]'::jsonb, '[]'::jsonb, '{"english_name":"Playfulness","type":"أساسي/فرعي","origin_body_part":"نظام المكافأة (VTA–nucleus accumbens)، قشرة أمام الجبهة، locus coeruleus"}'::jsonb)
ON CONFLICT (emotion_key) DO UPDATE SET arabic_name = EXCLUDED.arabic_name, category = EXCLUDED.category, definition = EXCLUDED.definition, body_sensations = EXCLUDED.body_sensations, triggers = EXCLUDED.triggers, healthy_expressions = EXCLUDED.healthy_expressions, metadata = EXCLUDED.metadata;
INSERT INTO public.emotions_encyclopedia (id, emotion_key, arabic_name, category, intensity_level, definition, body_sensations, triggers, healthy_expressions, metadata)
VALUES ('20000000-0000-0000-0000-000000000022', 'affection', 'مودة', 'اجتماعي / عاطفي / تقارب', 2, 'شعور دفء وعاطفة تجاه شخص أو كائن محبوب، يعبر عنه بالتواصل الجسدي أو العاطفي ويعزز الروابط الاجتماعية.', '["انخفاض ضغط الدم ومعدل نبض القلب","تنفس أعمق وأكثر انتظامًا","دفء عضلي وانتعاش جسدي","هدوء أعصاب وتوازن داخلي"]'::jsonb, '["العناق أو اللمسة الودية","التواصل البصري الحنون","تقديم دعم أو اهتمام، حتى بالكلمة","نزوع لحماية أو الاعتناء بالآخر","تكرار لقاءات مريحة ومحفّزة عاطفيًا"]'::jsonb, '[]'::jsonb, '{"english_name":"Affection","type":"فرعي","origin_body_part":"إفراز الأوكسيتوسين من الغدة النخامية، ثم تنشيط مسارات المكافأة וה–parasympathetic"}'::jsonb)
ON CONFLICT (emotion_key) DO UPDATE SET arabic_name = EXCLUDED.arabic_name, category = EXCLUDED.category, definition = EXCLUDED.definition, body_sensations = EXCLUDED.body_sensations, triggers = EXCLUDED.triggers, healthy_expressions = EXCLUDED.healthy_expressions, metadata = EXCLUDED.metadata;
INSERT INTO public.emotions_encyclopedia (id, emotion_key, arabic_name, category, intensity_level, definition, body_sensations, triggers, healthy_expressions, metadata)
VALUES ('20000000-0000-0000-0000-000000000023', 'warmth', 'دفء', 'اجتماعي / جسدي / تواصل', 2, 'احساس جسدي أو نفسي بالحرارة الحنونة، المرتبطة بالراحة، الثقة، والدفء الاجتماعي.', '["إحماء محلي في الجلد (اليدين، الصدر، الخدين)","انبساط الأوعية الدموية وانخفاض طفيف في ضغط الدم","تنفس أعمق ومرتاح","شعور عام بالاسترخاء والثراء الجسدي"]'::jsonb, '["تلامس بشيء دافئ – كوب قهوة ساخن أو بطانية","عناق أو لمسة حانية من شخص قريب","بيئة دافئة جسديًا – حرارة طبيعية لطيفة","تعاطف أو لطف من الآخرين","تفاعل اجتماعي داعم ومحب"]'::jsonb, '[]'::jsonb, '{"english_name":"Warmth","type":"أساسي/فرعي","origin_body_part":"تنشيط مستقبلات الحرارة الجلدية (TRPv3/4) وجسر الإحساس إلى القشرة الشمية والـinsula"}'::jsonb)
ON CONFLICT (emotion_key) DO UPDATE SET arabic_name = EXCLUDED.arabic_name, category = EXCLUDED.category, definition = EXCLUDED.definition, body_sensations = EXCLUDED.body_sensations, triggers = EXCLUDED.triggers, healthy_expressions = EXCLUDED.healthy_expressions, metadata = EXCLUDED.metadata;
INSERT INTO public.emotions_encyclopedia (id, emotion_key, arabic_name, category, intensity_level, definition, body_sensations, triggers, healthy_expressions, metadata)
VALUES ('20000000-0000-0000-0000-000000000024', 'euphoria', 'نشوة', 'إيجابية / مكافأة / ذروة الشعور', 2, 'حالة قوية من السعادة أو النشوة تتجاوز الشعور المعتاد بالفرح، غالبًا نتيجة تحفيز مكثف لنظام المكافأة في الدماغ.', '["خفقان طفيف ونشاط بدني مرتفع","زلزال داخلي يشبه الدفعة الطاقية","ضحك تلقائي أو ابتسامة واسعة","ارتخاء عام بعد الذروة"]'::jsonb, '["ممارسة نشاط بدني مكثّف (مثل الجري أو الرياضة الشديدة)","الاستماع إلى موسيقى مؤثرة خاصة تتسبب بــ chills","تحقيق إنجاز كبير أو مفاجئ","تجربة عاطفية قوية (مثل الحب، العلاقة الحميمة)","استخدام مواد تزيد من الدوبامين أو النورأدرينالين"]'::jsonb, '[]'::jsonb, '{"english_name":"Euphoria","type":"فرعي","origin_body_part":"تنشيط نظام المكافأة – VTA، nucleus accumbens، mesocorticolimbic pathways"}'::jsonb)
ON CONFLICT (emotion_key) DO UPDATE SET arabic_name = EXCLUDED.arabic_name, category = EXCLUDED.category, definition = EXCLUDED.definition, body_sensations = EXCLUDED.body_sensations, triggers = EXCLUDED.triggers, healthy_expressions = EXCLUDED.healthy_expressions, metadata = EXCLUDED.metadata;
INSERT INTO public.emotions_encyclopedia (id, emotion_key, arabic_name, category, intensity_level, definition, body_sensations, triggers, healthy_expressions, metadata)
VALUES ('20000000-0000-0000-0000-000000000025', 'inspiration', 'إلهام', 'إبداع / تحفيز / ارتفاع معنوي', 2, 'حالة تجمع بين الإثارة الفكرية والعاطفية، تدفع الشخص لرؤية ما هو أبعد من المألوف، وتحفيزه على خلق أو القيام بفعل ملهم.', '["زيادة خفيفة في معدل نبض القلب وتنفس منظم","إشارات تشاونيلز أو قشعريرة مرتبطة بالمكافأة","شعور بلفّة داخلية من الدفء والتركيز"]'::jsonb, '["الاستماع لموسيقى مؤثرة تحدث تشاونيلز (قشعريرة)","قراءة أو سماع قصة ذات معنى أو هدف سامي","ملاحظة إنجاز إنساني أو فني عظيم","تجارب طبيعية مذهلة أو مناظر فلكية","لغة قيادية تجمع بين رؤيا الجماعة والانتماء"]'::jsonb, '[]'::jsonb, '{"english_name":"Inspiration","type":"فرعي","origin_body_part":"تفاعل بين نظام المكافأة والقشرة الجبهيّة (PFC)، والمناطق الدافعية والعاطفية"}'::jsonb)
ON CONFLICT (emotion_key) DO UPDATE SET arabic_name = EXCLUDED.arabic_name, category = EXCLUDED.category, definition = EXCLUDED.definition, body_sensations = EXCLUDED.body_sensations, triggers = EXCLUDED.triggers, healthy_expressions = EXCLUDED.healthy_expressions, metadata = EXCLUDED.metadata;
INSERT INTO public.emotions_encyclopedia (id, emotion_key, arabic_name, category, intensity_level, definition, body_sensations, triggers, healthy_expressions, metadata)
VALUES ('20000000-0000-0000-0000-000000000026', 'kindness', 'لُطف', 'اجتماعي / عاطفي / إيجابية', 2, 'سلوك وُدّي يعبّر عن الاهتمام والدعم بدون مصلحة، يهدف لإحداث تأثير إيجابي على الآخرين والمحيط.', '["انخفاض ضغط الدم وتسارع نبضات القلب برفق","تنفس أبطأ وأكثر انتظامًا","استرخاء عضلي خفيف","تحسّن في التناغم العاطفي"]'::jsonb, '["مساعدة الآخرين دون مقابل","كلمات أو أفعال تُظهر احترام وتقدير","صرف ابتسامة أو تحيّة حنونة","الاستماع بانتباه لمن يحتاج للحديث","مشاركة وقتك ومواردك بحب"]'::jsonb, '[]'::jsonb, '{"english_name":"Kindness","type":"فرعي","origin_body_part":"تنشيط محور HPA وتأثير في الجهاز العصبي المركزي والوجيه"}'::jsonb)
ON CONFLICT (emotion_key) DO UPDATE SET arabic_name = EXCLUDED.arabic_name, category = EXCLUDED.category, definition = EXCLUDED.definition, body_sensations = EXCLUDED.body_sensations, triggers = EXCLUDED.triggers, healthy_expressions = EXCLUDED.healthy_expressions, metadata = EXCLUDED.metadata;
INSERT INTO public.emotions_encyclopedia (id, emotion_key, arabic_name, category, intensity_level, definition, body_sensations, triggers, healthy_expressions, metadata)
VALUES ('20000000-0000-0000-0000-000000000027', 'generosity', 'كرم', 'اجتماعي / عاطفي / إيجابية', 2, 'تصرف نابع من رغبة حقيقية في منح الوقت أو الموارد أو العطاء دون انتظار مقابل، يعزز رفاهية الآخرين وينعكس بمشاعر داخلية إيجابية للمانح.', '["خفض ضغط الدم وتخفيف توتر عضلي :contentReference[oaicite:1]{index=1}","تنفس أبطأ وأعمق بعد التفاعل الاجتماعي الإيجابي :contentReference[oaicite:2]{index=2}","إحساس helper’s high كنوع من النشوة الهادئة :contentReference[oaicite:3]{index=3}"]'::jsonb, '["رؤية حاجات تخص الآخرين قبل نفسك","استجابة لحالة حاجة أو ألم آخرين","نشاط تطوعي أو تقديم دعم دون مطالبة","فكرة التبرّع بصوت واعي وحر","رغبة في إحداث أثر إيجابي ملموس"]'::jsonb, '[]'::jsonb, '{"english_name":"Generosity","type":"فرعي"}'::jsonb)
ON CONFLICT (emotion_key) DO UPDATE SET arabic_name = EXCLUDED.arabic_name, category = EXCLUDED.category, definition = EXCLUDED.definition, body_sensations = EXCLUDED.body_sensations, triggers = EXCLUDED.triggers, healthy_expressions = EXCLUDED.healthy_expressions, metadata = EXCLUDED.metadata;
INSERT INTO public.emotions_encyclopedia (id, emotion_key, arabic_name, category, intensity_level, definition, body_sensations, triggers, healthy_expressions, metadata)
VALUES ('20000000-0000-0000-0000-000000000028', 'motivation', 'دافع', 'معرفي / عاطفي / سلوكي', 2, 'عملية داخلية تبدأ، توجه، وتدعم السلوك لتحقيق هدف معين؛ يمكن أن تكون نابعة من رغبة داخلية أو نتيجة لمكافأة خارجية.', '["طاقة وتركيز متزايد","ارتفاع خفيف في معدل التنفس ونبض القلب","استمرارية الشعور بالهدف","انخفاض التوتر إذا كان محفّزًا إيجابيًا"]'::jsonb, '["رغبة داخلية في التعلم أو الاستمتاع (فضول–تدفق)","مكافآت خارجية (مال، تقدير، تجنب عقاب)","الحاجة لتقليل توتر داخلي (جوع، تعب، قلق)","تحفيز لقاء تحدّ أو مهمة مثيرة"]'::jsonb, '[]'::jsonb, '{"english_name":"Motivation","type":"أساسي","origin_body_part":"نظام المكافأة – VTA، nucleus accumbens، vmPFC، insula"}'::jsonb)
ON CONFLICT (emotion_key) DO UPDATE SET arabic_name = EXCLUDED.arabic_name, category = EXCLUDED.category, definition = EXCLUDED.definition, body_sensations = EXCLUDED.body_sensations, triggers = EXCLUDED.triggers, healthy_expressions = EXCLUDED.healthy_expressions, metadata = EXCLUDED.metadata;
INSERT INTO public.emotions_encyclopedia (id, emotion_key, arabic_name, category, intensity_level, definition, body_sensations, triggers, healthy_expressions, metadata)
VALUES ('20000000-0000-0000-0000-000000000029', 'altruism', 'إيثار', 'اجتماعي / أخلاقي / عاطفي', 2, 'سلوك تضحي فيه بمصلحتك أو راحتك لمصلحة شخص آخر، حتى لو لم يكن هناك مقابل مادي أو مصلحة مباشرة.', '["انخفاض مؤقت في ضغط الدم والتوتر بعد الفعل :contentReference[oaicite:1]{index=1}","تنفس أبطأ وراحة جسدية تطوف داخليًا :contentReference[oaicite:2]{index=2}"]'::jsonb, '["رؤية شخص بحاجة بدون توقع مقابل","تبرع أو مساعدة دون مقابل","الاستجابة لمعاناة الآخرين","مشاركة الموارد بشكل غير أناني","عاطفة عميقة تجاه شخص غريب أو محتاج"]'::jsonb, '[]'::jsonb, '{"english_name":"Altruism","type":"فرعي"}'::jsonb)
ON CONFLICT (emotion_key) DO UPDATE SET arabic_name = EXCLUDED.arabic_name, category = EXCLUDED.category, definition = EXCLUDED.definition, body_sensations = EXCLUDED.body_sensations, triggers = EXCLUDED.triggers, healthy_expressions = EXCLUDED.healthy_expressions, metadata = EXCLUDED.metadata;
INSERT INTO public.emotions_encyclopedia (id, emotion_key, arabic_name, category, intensity_level, definition, body_sensations, triggers, healthy_expressions, metadata)
VALUES ('20000000-0000-0000-0000-000000000030', 'forgiveness', 'غفران', 'عاطفي / نفسي / صحة', 2, 'تخلي الوعي عن الاستياء والغل تجاه طرف أساء لك، مع بناء شعور إيجابي داخلي، حتى دون الحاجة لمصالحة أو اعتذار.', '["انخفاض في ضغط الدم ومعدل ضربات القلب عند استدعاء مواقف غفران :contentReference[oaicite:1]{index=1}","تراجع في استجابة التعصب العضلي (corrugator EMG) والتهيج الجسدي :contentReference[oaicite:2]{index=2}","تنفس أهدأ وأعمق بعد الغفران والطمأنينة الداخلية :contentReference[oaicite:3]{index=3}"]'::jsonb, '["قرار واعي بالتخلي عن الرغبة في الانتقام","ممارسة إعادة تأطير الموقف بفهم دوافع الطرف الآخر","كتابة أو قول نية الغفران بصوت عالٍ أو كتابة","تخيل لحظة الصفح أو تسامح رمزي (مثل تجسيد الاعتذار)","تمارين علاجية موجهة تدعم الصفح (مثل ممارسة الرحمة)"]'::jsonb, '[]'::jsonb, '{"english_name":"Forgiveness","type":"فرعي"}'::jsonb)
ON CONFLICT (emotion_key) DO UPDATE SET arabic_name = EXCLUDED.arabic_name, category = EXCLUDED.category, definition = EXCLUDED.definition, body_sensations = EXCLUDED.body_sensations, triggers = EXCLUDED.triggers, healthy_expressions = EXCLUDED.healthy_expressions, metadata = EXCLUDED.metadata;
INSERT INTO public.emotions_encyclopedia (id, emotion_key, arabic_name, category, intensity_level, definition, body_sensations, triggers, healthy_expressions, metadata)
VALUES ('20000000-0000-0000-0000-000000000031', 'inner-contentment', 'اكتفاء داخلي', 'إيجابية / استقرار نفسي / قبول الذات', 2, 'حالة شعورية عميقة تجعل الشخص يشعر بالرضا التام عن ذاته وحياته الحالية بدون الحاجة لمزيد أو ظروف خارجية.', '["انخفاض الكورتيزول وضغط الدم","تنفس منتظم أهدأ","استرخاء عضلي عام","زيادة تباين ضربات القلب (HRV)"]'::jsonb, '["قبول النفس كما هي دون مقارنة","تقدير الحاضر وممارسة الامتنان","تحقيق توازن بين التوقعات والواقع","تحقيق إنجاز معتدل أو نقد ذاتي إيجابي","استقلالية نفسية وعدم تَبع حالة الآخرين"]'::jsonb, '[]'::jsonb, '{"english_name":"Inner Contentment","type":"فرعي"}'::jsonb)
ON CONFLICT (emotion_key) DO UPDATE SET arabic_name = EXCLUDED.arabic_name, category = EXCLUDED.category, definition = EXCLUDED.definition, body_sensations = EXCLUDED.body_sensations, triggers = EXCLUDED.triggers, healthy_expressions = EXCLUDED.healthy_expressions, metadata = EXCLUDED.metadata;
INSERT INTO public.emotions_encyclopedia (id, emotion_key, arabic_name, category, intensity_level, definition, body_sensations, triggers, healthy_expressions, metadata)
VALUES ('20000000-0000-0000-0000-000000000032', 'freedom', 'حرية', 'إيجابي / إدراكي / نفسي', 2, 'شعور بالقدرة على اتخاذ اختيارات شخصية دون قيود أو تهديدات خارجية، يشمل الحرية من (constraints) والحرية للـ (agency).', '["انخفاض في مستويات الكورتيزول والقلق :contentReference[oaicite:1]{index=1}","زيادة الثقة بالنفس والقدرة على المبادرة","راحة وانفتاح جسدي عند الشعور بالأمان"]'::jsonb, '["إدراك القدرة على اتخاذ قرار مستقل","غياب ضغوط أو تهديدات خارجية","وجود خيارات واقعية متعددة","الشعور بالتحكم الذاتي (autonomy)","التوازن بين الاختيار والمسؤولية"]'::jsonb, '[]'::jsonb, '{"english_name":"Freedom","type":"فرعي"}'::jsonb)
ON CONFLICT (emotion_key) DO UPDATE SET arabic_name = EXCLUDED.arabic_name, category = EXCLUDED.category, definition = EXCLUDED.definition, body_sensations = EXCLUDED.body_sensations, triggers = EXCLUDED.triggers, healthy_expressions = EXCLUDED.healthy_expressions, metadata = EXCLUDED.metadata;
INSERT INTO public.emotions_encyclopedia (id, emotion_key, arabic_name, category, intensity_level, definition, body_sensations, triggers, healthy_expressions, metadata)
VALUES ('20000000-0000-0000-0000-000000000033', 'clarity', 'وضوح', 'معرفي / عاطفي / إدراكي', 2, 'حالة ذهنية وعاطفية يتمكن فيها الشخص من تمييز أفكاره ومشاعره بوضوح، مع قدرة على التركيز بدون تشويش داخلي أو خارجي.', '["انخفاض في مستويات التوتر (الكورتيزول)","تنفس أبطأ وأهدأ","استقرار في نبضات القلب وتباين جيد (HRV)","استجابة عضلية أقل توتراً"]'::jsonb, '["ممارسة اليقظة الذهنية (mindfulness)","إعادة تأطير الأفكار السلبية (CBT)","إيقاف التشويش بالفوضى والتركيز على مهمة واحدة","كتابة اليوميات أو التعبير عن المشاعر","مارسات تنظيمية مثل النوم الجيد، الرياضة، وتقليل الإزعاج"]'::jsonb, '[]'::jsonb, '{"english_name":"Clarity","type":"فرعي"}'::jsonb)
ON CONFLICT (emotion_key) DO UPDATE SET arabic_name = EXCLUDED.arabic_name, category = EXCLUDED.category, definition = EXCLUDED.definition, body_sensations = EXCLUDED.body_sensations, triggers = EXCLUDED.triggers, healthy_expressions = EXCLUDED.healthy_expressions, metadata = EXCLUDED.metadata;
INSERT INTO public.emotions_encyclopedia (id, emotion_key, arabic_name, category, intensity_level, definition, body_sensations, triggers, healthy_expressions, metadata)
VALUES ('20000000-0000-0000-0000-000000000034', 'respect', 'احترام', 'اجتماعي / عاطفي / إدراكي', 2, 'شعور وتقدير تجاه شخص أو سلوك يُعَدّ ذا قيمة، يرتكز على الاعتراف بالكرامة والكفاءة ويولد تفاعلًا واعيًا وودودًا.', '["استرخاء ملحوظ بعد الإحساس بالتقدير","تواصل بصري منتظم ولغة جسد منفتحة","نبرة صوت هادئة ورقيقة عند مخاطبة الشخص المحترم"]'::jsonb, '["رؤية سلوك أخلاقي أو مهني متميّز","التقدير المُتواصل والداعم للفرد","الاستماع الفعّال دون مقاطعة","إظهار الاعتراف بمكانة الآخر أو خبرته","تقدير الاختلاف الشخصي أو الخلفيات الجغرافية"]'::jsonb, '[]'::jsonb, '{"english_name":"Respect","type":"فرعي","origin_body_part":"مشاعر في الدماغ لا تعتمد على التفكير الواعي، بمشاركة الماضي والسياق الاجتماعي"}'::jsonb)
ON CONFLICT (emotion_key) DO UPDATE SET arabic_name = EXCLUDED.arabic_name, category = EXCLUDED.category, definition = EXCLUDED.definition, body_sensations = EXCLUDED.body_sensations, triggers = EXCLUDED.triggers, healthy_expressions = EXCLUDED.healthy_expressions, metadata = EXCLUDED.metadata;
INSERT INTO public.emotions_encyclopedia (id, emotion_key, arabic_name, category, intensity_level, definition, body_sensations, triggers, healthy_expressions, metadata)
VALUES ('20000000-0000-0000-0000-000000000035', 'awe', 'انبهار', 'إيجابي / استكشاف / استجابة فطرية', 2, 'شعور بالدهشة والإعجاب العميق تجاه شيء هائل أو مُبهر يتجاوز التوقعات، يصاحبه شعور بـ“صغر الذات” وتوسيع الإدراك.', '["تجمّد فوري مصحوب بقشعريرة (goosebumps) :contentReference[oaicite:1]{index=1}","بطء مؤقت في ضربات القلب وتنفس مرتكز :contentReference[oaicite:2]{index=2}","تنشيط parasympathetic مع خفض actividad sympathetic :contentReference[oaicite:3]{index=3}","اتساع حدقة العين وتعبير وجه يشمل حاجب مرفوع وفم منفتح :contentReference[oaicite:4]{index=4}"]'::jsonb, '["مشاهد طبيعية ضخمة (جبال، بحر، فضاء)","فن مهيب أو عمارة عظيمة","قصص بطولية أو مواقف أخلاقية ملهمة","لحظة عاطفية قوية (ولادة، موت)","موسيقى تؤدي إلى قشعريرة (frisson)"]'::jsonb, '[]'::jsonb, '{"english_name":"Awe","type":"أساسي"}'::jsonb)
ON CONFLICT (emotion_key) DO UPDATE SET arabic_name = EXCLUDED.arabic_name, category = EXCLUDED.category, definition = EXCLUDED.definition, body_sensations = EXCLUDED.body_sensations, triggers = EXCLUDED.triggers, healthy_expressions = EXCLUDED.healthy_expressions, metadata = EXCLUDED.metadata;
INSERT INTO public.emotions_encyclopedia (id, emotion_key, arabic_name, category, intensity_level, definition, body_sensations, triggers, healthy_expressions, metadata)
VALUES ('20000000-0000-0000-0000-000000000036', 'spiritual-trust', 'ثقة روحية', 'روحاني / نفسي / ديني', 2, 'شعور داخلي عميق بالاعتماد على قوة أو اقتناع روحي، يمنح استقرارًا وثقة في مواجهة الغموض أو التحديات.', '["انخفاض الكورتيزول وراحة في الجسد","تنفس أبطأ وأعمق دون جهد","هدوء داخلي ينبع من يقين روحي"]'::jsonb, '["ممارسة تأمل/دعاء منتظم","تأمل في قصص روحية تطرح العظة والهدى","تحقيق نتائج بعد تكرار لممارسات روحية","قراءة أو سماع كلمات مفعمة باليقين"]'::jsonb, '[]'::jsonb, '{"english_name":"Spiritual Trust","type":"فرعي"}'::jsonb)
ON CONFLICT (emotion_key) DO UPDATE SET arabic_name = EXCLUDED.arabic_name, category = EXCLUDED.category, definition = EXCLUDED.definition, body_sensations = EXCLUDED.body_sensations, triggers = EXCLUDED.triggers, healthy_expressions = EXCLUDED.healthy_expressions, metadata = EXCLUDED.metadata;
INSERT INTO public.emotions_encyclopedia (id, emotion_key, arabic_name, category, intensity_level, definition, body_sensations, triggers, healthy_expressions, metadata)
VALUES ('20000000-0000-0000-0000-000000000037', 'faith', 'إيمان', 'روحاني / ديني / إدراكي', 2, 'اقتناع عميق ومستمر بقيمة أو وجود روحاني أو قوة عُليا، يمتد ليشمل الثقة بالنفس والآخرين والمستقبل رغم عدم وجود دليل مادي.', '["نشاط في الدوبامين ونواة المكافأة (مثل الشعور بالإثارة الداخلية) :contentReference[oaicite:4]{index=4}","تنفس خفيف ودفء نفسي عند التماس فوري أو تجارب روحية"]'::jsonb, '["ممارسة الصلاة أو التاومي̈ل بانتظام","قصص ملهمة تبعث النور في القلب","تجارب غيبيّة أو لحظات إدراك داخلي","إعادة تكرار كلمات أو تأملات روحية"]'::jsonb, '[]'::jsonb, '{"english_name":"Faith","type":"أساسي"}'::jsonb)
ON CONFLICT (emotion_key) DO UPDATE SET arabic_name = EXCLUDED.arabic_name, category = EXCLUDED.category, definition = EXCLUDED.definition, body_sensations = EXCLUDED.body_sensations, triggers = EXCLUDED.triggers, healthy_expressions = EXCLUDED.healthy_expressions, metadata = EXCLUDED.metadata;
INSERT INTO public.emotions_encyclopedia (id, emotion_key, arabic_name, category, intensity_level, definition, body_sensations, triggers, healthy_expressions, metadata)
VALUES ('20000000-0000-0000-0000-000000000038', 'admiration', 'إعجاب', 'اجتماعي / عاطفي / إيجابية', 2, 'شعور إيجابي ينشأ عند رؤية شخص أو سلوك يتّسم بالكفاءة أو الفضيلة أو الجمال الذي يتجاوز التوقعات، ويحفّز الرغبة في الاقتداء والتحسن الذاتي.', '["إحساس بالقشعريرة (frisson)، خاصة عند الإعجاب بموهبة أو أخلاق :contentReference[oaicite:1]{index=1}","زيادة نشاط بدني خفيف (نشاط خفيف بالقلب والتنفس) نتيجة التحمّس","ابتسامة أو نظرة مديدة بتعبّر عن التقدير"]'::jsonb, '["مشاهدة أداء متميز أو موهبة فائقة","رؤية تصرف أخلاقي نادر أو ملهم","مشهد فني أو إبداعي مذهل","شخص يجمع بين الكفاءة والعطاء دون فروق","التعرّف على قصة نجاح صعبة وتجاوز للتحديات"]'::jsonb, '[]'::jsonb, '{"english_name":"Admiration","type":"فرعي"}'::jsonb)
ON CONFLICT (emotion_key) DO UPDATE SET arabic_name = EXCLUDED.arabic_name, category = EXCLUDED.category, definition = EXCLUDED.definition, body_sensations = EXCLUDED.body_sensations, triggers = EXCLUDED.triggers, healthy_expressions = EXCLUDED.healthy_expressions, metadata = EXCLUDED.metadata;
INSERT INTO public.emotions_encyclopedia (id, emotion_key, arabic_name, category, intensity_level, definition, body_sensations, triggers, healthy_expressions, metadata)
VALUES ('20000000-0000-0000-0000-000000000039', 'sense-of-completeness', 'إحساس بالكمال', 'نفسية / إيجابي / استقرار داخلي', 2, 'إحساس داخلي بأن الذات متكاملة، خالية من النقص، ويترافق مع رضا ذاتي عميق وتوازن نفسي.', '["انخفاض كبير في الكورتيزول وضغط الدم","تنفس هادئ ومنتظم دون جهد","راحة عضلية شاملة وانتعاش داخلي","توازن في نبض القلب (HRV مرتفعة)"]'::jsonb, '["تحقيق إنجاز معنوي أو تجديد داخلي","تجاوز مرحلة صراع داخلي أو شفاء نفسي","تجارب اتحاد روحي أو لحظات تأمل عميقة","قبول الذات دون شروط مقارنة","شعور بأن الحياة في اتزان بين الذات والعالم"]'::jsonb, '[]'::jsonb, '{"english_name":"Sense of Completeness","type":"فرعي"}'::jsonb)
ON CONFLICT (emotion_key) DO UPDATE SET arabic_name = EXCLUDED.arabic_name, category = EXCLUDED.category, definition = EXCLUDED.definition, body_sensations = EXCLUDED.body_sensations, triggers = EXCLUDED.triggers, healthy_expressions = EXCLUDED.healthy_expressions, metadata = EXCLUDED.metadata;
INSERT INTO public.emotions_encyclopedia (id, emotion_key, arabic_name, category, intensity_level, definition, body_sensations, triggers, healthy_expressions, metadata)
VALUES ('20000000-0000-0000-0000-000000000040', 'internal-balance-stability', 'اتزان داخلي وثبات', 'نفسية / ترتيب داخلي / تنظيم عاطفي', 2, 'حالة من التوازن النفسي والجسدي، حيث يتمكن الإنسان من تنظيم انفعالاته وتبعاته العصبية بغض النظر عن الضغوط أو المواقف الحياتية.', '["انخفاض الكورتيزول وضغط الدم :contentReference[oaicite:1]{index=1}","تنفس أهدأ وأكثر انتظامًا وانبساط عضلي","نسبة تباين قلب (HRV) مرتفعة تشير لقدرة ذات عنوان التنظيم الداخلي :contentReference[oaicite:2]{index=2}"]'::jsonb, '["التأمل واليقظة الذهنية المنتظمة","ممارسة التنفس البطني وتمارين التهدئة","النوم الجيد والروتين الصحي","كتابة المشاعر وتنظيم الأفكار","مواجهة الضغوط باستخدام استراتيجيات التحكم الذاتي"]'::jsonb, '[]'::jsonb, '{"english_name":"Internal Balance & Stability","type":"فرعي"}'::jsonb)
ON CONFLICT (emotion_key) DO UPDATE SET arabic_name = EXCLUDED.arabic_name, category = EXCLUDED.category, definition = EXCLUDED.definition, body_sensations = EXCLUDED.body_sensations, triggers = EXCLUDED.triggers, healthy_expressions = EXCLUDED.healthy_expressions, metadata = EXCLUDED.metadata;
INSERT INTO public.emotions_encyclopedia (id, emotion_key, arabic_name, category, intensity_level, definition, body_sensations, triggers, healthy_expressions, metadata)
VALUES ('20000000-0000-0000-0000-000000000041', 'acceptance', 'تقبّل', 'عاطفي / معرفي / تنظيم نفسي', 2, 'قدرة واعية على قبول المشاعر والأفكار بدون حكم أو مقاومة، مما يقلل من شدة الاستجابة العاطفية ويزيد الصحة النفسية.', '["انخفاض معدل التنفس ومعدل ضربات القلب :contentReference[oaicite:1]{index=1}","انخفاض الكورتيزول والتوتر الجسدي :contentReference[oaicite:2]{index=2}"]'::jsonb, '["ممارسة اليقظة الذهنية (mindfulness)","تذكّر ''افترض أن ما يحدث هو ما يحدث'' بدون محاكمة","التدريب على قبول الألم أو العجز العاطفي","استخدام تقنيات ACT (الرؤية الخارجية، التفكيك)","تمارين التنفس والتركيز على الحاضر"]'::jsonb, '[]'::jsonb, '{"english_name":"Acceptance","type":"فرعي"}'::jsonb)
ON CONFLICT (emotion_key) DO UPDATE SET arabic_name = EXCLUDED.arabic_name, category = EXCLUDED.category, definition = EXCLUDED.definition, body_sensations = EXCLUDED.body_sensations, triggers = EXCLUDED.triggers, healthy_expressions = EXCLUDED.healthy_expressions, metadata = EXCLUDED.metadata;
INSERT INTO public.emotions_encyclopedia (id, emotion_key, arabic_name, category, intensity_level, definition, body_sensations, triggers, healthy_expressions, metadata)
VALUES ('20000000-0000-0000-0000-000000000042', 'empowerment', 'تمكين', 'نفسي / اجتماعي / إداري', 2, 'الشعور بالقدرة على التحكم في الحياة واتخاذ القرارات، مع إحساس بالقيمة الذاتية والتأثير في الواقع المحيط.', '["انخفاض التعب والإرهاق النفسي :contentReference[oaicite:1]{index=1}","نشاط بدني وخفيف نتيجة تحفيز الوصول للنتائج","راحة وانتعاش داخلي عند الإحساس بالتحكّم"]'::jsonb, '["إتاحة مساحة للتحكم بالقرارات","اكتساب مهارات جديدة بثقة","تحمل المسؤولية والنجاح فيها","دعم قيادي أو اجتماعي يبني الثقة","بيئة تحفّز المشاركة والمبادرة"]'::jsonb, '[]'::jsonb, '{"english_name":"Empowerment","type":"فرعي"}'::jsonb)
ON CONFLICT (emotion_key) DO UPDATE SET arabic_name = EXCLUDED.arabic_name, category = EXCLUDED.category, definition = EXCLUDED.definition, body_sensations = EXCLUDED.body_sensations, triggers = EXCLUDED.triggers, healthy_expressions = EXCLUDED.healthy_expressions, metadata = EXCLUDED.metadata;
INSERT INTO public.emotions_encyclopedia (id, emotion_key, arabic_name, category, intensity_level, definition, body_sensations, triggers, healthy_expressions, metadata)
VALUES ('20000000-0000-0000-0000-000000000043', 'feeling-of-strength', 'شعور بالقوة', 'نفسي / جسدي / تمكين', 2, 'الإحساس الداخلي بالقدرة الجسدية أو النفسية على تجاوز التحديات، ينبع من الثقة بالكفاءات الذاتية.', '["ارتفاع خفيف في طاقة الجسم وأنفاس منتظمة :contentReference[oaicite:4]{index=4}","نشاط بدني من السلطة الداخلية وتحفيز الإندورفين","تحسن في التوازن الجسدي والارتياح بعد الإجراءات"]'::jsonb, '["تحقيق إنجازات فعلية أو ذهنية","تصوّر النجاح قبل تنفيذه ذهنياً","تمييز مستمر للتقدم والنمو الشخصي","تصفيق الذات على الانتصارات اليومية"]'::jsonb, '[]'::jsonb, '{"english_name":"Feeling of Strength","type":"فرعي"}'::jsonb)
ON CONFLICT (emotion_key) DO UPDATE SET arabic_name = EXCLUDED.arabic_name, category = EXCLUDED.category, definition = EXCLUDED.definition, body_sensations = EXCLUDED.body_sensations, triggers = EXCLUDED.triggers, healthy_expressions = EXCLUDED.healthy_expressions, metadata = EXCLUDED.metadata;
INSERT INTO public.emotions_encyclopedia (id, emotion_key, arabic_name, category, intensity_level, definition, body_sensations, triggers, healthy_expressions, metadata)
VALUES ('20000000-0000-0000-0000-000000000044', 'serendipity', 'مصادفة سعيدة', 'إيجابي / استكشاف / مصادفة', 2, 'اكتشاف مفيد أو تجربة إيجابية تحدث بالصدفة، دون توقع أو تخطيط مسبق، ويُشعرك بأنها ''حسن طالع''.', '["قشعريرة خفيفة (goosebumps) نتيجة الدهشة والفرحة :contentReference[oaicite:1]{index=1}","تسارع مؤقت في القلب وتنفس متحفّز","تنشيط الجهاز العصبي اللامركزي – استجابة عطائية ومزاج هادئ بعد الدهشة :contentReference[oaicite:2]{index=2}"]'::jsonb, '["انفتاح ذهني وفضول للمحيط","حضور لحظات عابرة واستعداد للتقاط الإشارات","تفاعل اجتماعي عفوي بعيدًا عن الخطة","بحث عن شيء محدد وظهور شيء آخر مفيد","بيئة تدعم الاستكشاف بعقلية منفتحة"]'::jsonb, '[]'::jsonb, '{"english_name":"Serendipity","type":"فرعي"}'::jsonb)
ON CONFLICT (emotion_key) DO UPDATE SET arabic_name = EXCLUDED.arabic_name, category = EXCLUDED.category, definition = EXCLUDED.definition, body_sensations = EXCLUDED.body_sensations, triggers = EXCLUDED.triggers, healthy_expressions = EXCLUDED.healthy_expressions, metadata = EXCLUDED.metadata;
INSERT INTO public.emotions_encyclopedia (id, emotion_key, arabic_name, category, intensity_level, definition, body_sensations, triggers, healthy_expressions, metadata)
VALUES ('20000000-0000-0000-0000-000000000045', 'self-transcendence', 'ارتقاء نفسي', 'روحي / نفسي / وجودي', 2, 'تجاوز حدود الذات الشخصية عبر تجربة اتصال بكيان أو قيمة أكبر من الذات، مما يولد معنى أعمق، سلام داخلي، وهدف تفاؤلي.', '["قشعريرة أو رعشة عاطفية أثناء اللحظة ","سرعة مؤقتة في نبض القلب وتنفس منتظم","شعور بالهدوء العميق بعد التجربة"]'::jsonb, '["تأمل عميق أو تفاعل مع الطبيعة","مواقف روحية أو إبداعية (موسيقى/فن/عمارة)","ممارسة رحمة أو خدمة للآخر","قراءة/استماعا لقصص معنوية عالية"]'::jsonb, '[]'::jsonb, '{"english_name":"Self-Transcendence","type":"أساسي"}'::jsonb)
ON CONFLICT (emotion_key) DO UPDATE SET arabic_name = EXCLUDED.arabic_name, category = EXCLUDED.category, definition = EXCLUDED.definition, body_sensations = EXCLUDED.body_sensations, triggers = EXCLUDED.triggers, healthy_expressions = EXCLUDED.healthy_expressions, metadata = EXCLUDED.metadata;
INSERT INTO public.emotions_encyclopedia (id, emotion_key, arabic_name, category, intensity_level, definition, body_sensations, triggers, healthy_expressions, metadata)
VALUES ('20000000-0000-0000-0000-000000000046', 'reverent-humility-positive-awe', 'خشوع ورهبة إيجابية', 'روحاني / نفسي / إدراكي', 2, 'حالة من الإحساس العميق بالاجلال والاحترام أمام كيان أو تجربة أكبر من الذات، تتأرجح بين التذلل والاتساع النفسي، لكنها تنتهي بشعور بالقرب والطمأنينة.', '["تسارع مؤقت للنفس والتنفس العميق المصاحب للخشوع :contentReference[oaicite:1]{index=1}","انخفاض الضغط والقلب بعد التجربة :contentReference[oaicite:2]{index=2}","قشعريرة وارتجاف خفيف – علامة رهبة إيجابية :contentReference[oaicite:3]{index=3}"]'::jsonb, '["التأمل في عظمة الله أو الطبيعة","تلاوة آيات عظيمة أو استماع لقصص نبوية","حضور لحظات صلاة بخشوع (khushūʿ)","مشاهدة مشهد طبيعي أو فني يوقظ القلب","طقوس روحية تشعر بالاتصال بالخالق"]'::jsonb, '[]'::jsonb, '{"english_name":"Reverent Humility & Positive Awe","type":"أساسي"}'::jsonb)
ON CONFLICT (emotion_key) DO UPDATE SET arabic_name = EXCLUDED.arabic_name, category = EXCLUDED.category, definition = EXCLUDED.definition, body_sensations = EXCLUDED.body_sensations, triggers = EXCLUDED.triggers, healthy_expressions = EXCLUDED.healthy_expressions, metadata = EXCLUDED.metadata;
INSERT INTO public.emotions_encyclopedia (id, emotion_key, arabic_name, category, intensity_level, definition, body_sensations, triggers, healthy_expressions, metadata)
VALUES ('20000000-0000-0000-0000-000000000047', 'companionship-affectionate-presence', 'رفقة ومؤانسة', 'العلاقات / الانتماء / الحميمية', 2, 'حالة من الشعور بالطمأنينة والراحة الناتجة عن وجود شخص قريب، حاضر بكيانه ومشاعره، يشعرنا بأننا لسنا وحدنا في هذا العالم.', '["استرخاء عضلي واضح","دفء محسوس في القلب أو الصدر","انخفاض الكورتيزول","ارتفاع طفيف في الأوكسيتوسين","تنظيم ضربات القلب"]'::jsonb, '["الجلوس مع شخص نحبه دون الحاجة للكلام","وجود صديق حقيقي وقت الشدة","نظرة حنونة من شخص قريب","لمسة مريحة على الكتف أو اليد","ضحكة مشتركة صادقة"]'::jsonb, '[]'::jsonb, '{"english_name":"Companionship & Affectionate Presence","type":"شعور مركب"}'::jsonb)
ON CONFLICT (emotion_key) DO UPDATE SET arabic_name = EXCLUDED.arabic_name, category = EXCLUDED.category, definition = EXCLUDED.definition, body_sensations = EXCLUDED.body_sensations, triggers = EXCLUDED.triggers, healthy_expressions = EXCLUDED.healthy_expressions, metadata = EXCLUDED.metadata;
INSERT INTO public.emotions_encyclopedia (id, emotion_key, arabic_name, category, intensity_level, definition, body_sensations, triggers, healthy_expressions, metadata)
VALUES ('20000000-0000-0000-0000-000000000048', 'vitality-energy', 'حيوية وطاقة', 'جسدي / نفسي / إدراكي', 2, 'حالة ملؤها النشاط البدني والذهني، تمنح الشعور بالقوة، اليقظة، والإنتاجية المستمرة.', '["ارتفاع مؤقت في النبض والتنفس مع الراحة بعد الجهد","انخفاض في الكورتيزول وزيادة HRV – دليل على صحة تحفيزية :contentReference[oaicite:2]{index=2}","مستويات عالية من BDNF وIGF‑1 تعزز بقاء الخلايا العصبية ونمو الدماغ :contentReference[oaicite:3]{index=3}"]'::jsonb, '["الرياضة الهوائية المنتظمة (30 دقيقة يومياً)","تغذية متوازنة مع بروتينات، أوميغا‑3، فيتامينات ومعادن :contentReference[oaicite:1]{index=1}","نوم جيد وروتين يوم منتظم","تنفس عميق وتمارين تهدئة أو يوجا","نشاطات ممتعة مرتبطة بالإنتاجية"]'::jsonb, '[]'::jsonb, '{"english_name":"Vitality & Energy","type":"مركب"}'::jsonb)
ON CONFLICT (emotion_key) DO UPDATE SET arabic_name = EXCLUDED.arabic_name, category = EXCLUDED.category, definition = EXCLUDED.definition, body_sensations = EXCLUDED.body_sensations, triggers = EXCLUDED.triggers, healthy_expressions = EXCLUDED.healthy_expressions, metadata = EXCLUDED.metadata;
INSERT INTO public.emotions_encyclopedia (id, emotion_key, arabic_name, category, intensity_level, definition, body_sensations, triggers, healthy_expressions, metadata)
VALUES ('20000000-0000-0000-0000-000000000049', 'childlike-happiness-joy', 'سعادة طفولية وبهجة', 'عاطفي / اجتماعي / إدراكي', 2, 'إحساس بسيط، نقي، ينبع من اللحظة وظروفها دون توقع، يعكس حياة الطفولة حيث الفرح يأتي من أشياء بسيطة وعفوية.', '["ابتسامة واسعة وصادقة تلامس العينين (Duchenne smile) :contentReference[oaicite:1]{index=1}","تنفس مرتفع ونبض ينبض بالحياة (buzzing) :contentReference[oaicite:2]{index=2}","قشعريرة خفيفة أو إثارة جسدية – علامة فرح طفولي"]'::jsonb, '["اللعب بحرية مع الأصدقاء أو بمفردك","اكتشاف شيء بسيط لأول مرة (مثال: رشفة شاي سادة)","مواقف غير مخططة مضحكة","مشاركة وجبة أو ضحكة مرحة مع الأسرة","تلقي حضن أو لمسة حانية دون سبب"]'::jsonb, '[]'::jsonb, '{"english_name":"Childlike Happiness & Joy","type":"أساسي"}'::jsonb)
ON CONFLICT (emotion_key) DO UPDATE SET arabic_name = EXCLUDED.arabic_name, category = EXCLUDED.category, definition = EXCLUDED.definition, body_sensations = EXCLUDED.body_sensations, triggers = EXCLUDED.triggers, healthy_expressions = EXCLUDED.healthy_expressions, metadata = EXCLUDED.metadata;
INSERT INTO public.emotions_encyclopedia (id, emotion_key, arabic_name, category, intensity_level, definition, body_sensations, triggers, healthy_expressions, metadata)
VALUES ('20000000-0000-0000-0000-000000000050', 'positive-astonishment', 'ذهول إيجابي', 'معرفي / عاطفي / إدراكي', 2, 'شعور مفاجئ بالدهشة والإعجاب يحدث عندما تواجه شيئاً غير متوقع يثير الإعجاب دون تهديد، مركّز على الفرص والإدراك الواسع.', '["رفع مفاجئ في الحواجب واتساع العين (تعابير وجه مفاجئ) :contentReference[oaicite:1]{index=1}","قشعريرة خفيفة أو goosebumps – علامة دهشة إيجابية :contentReference[oaicite:2]{index=2}","خفقان طفيف وتنفس سريع مؤقت يعقبه هدوء"]'::jsonb, '["رؤية شيء نادر أو مفاجئ لكن جميل","لامسة جديدة للمعرفة تثير السؤال","قصص أو تجارب تغير منظورك بشكل لطيف","فن أو موسيقى تلامس عمق الإحساس"]'::jsonb, '[]'::jsonb, '{"english_name":"Positive Astonishment","type":"أساسي"}'::jsonb)
ON CONFLICT (emotion_key) DO UPDATE SET arabic_name = EXCLUDED.arabic_name, category = EXCLUDED.category, definition = EXCLUDED.definition, body_sensations = EXCLUDED.body_sensations, triggers = EXCLUDED.triggers, healthy_expressions = EXCLUDED.healthy_expressions, metadata = EXCLUDED.metadata;
INSERT INTO public.emotions_encyclopedia (id, emotion_key, arabic_name, category, intensity_level, definition, body_sensations, triggers, healthy_expressions, metadata)
VALUES ('20000000-0000-0000-0000-000000000051', 'innocence', 'براءة', 'معرفي / عاطفي / اجتماعي', 2, 'خلو النفس من الذنب أو الاستقامة أو الزمن القاسي، تتجسّد كصفاء داخلي وصدق تلقائي يبدأ من غياب التلوث النفسي.', '["ابتسامة Duchenne – صادقة وتَضيء العينين :contentReference[oaicite:1]{index=1}","تنفس متناسق أبطأ، جسد يرتاح تلقائيًا :contentReference[oaicite:2]{index=2}","انخفاض الكورتيزول عند تجلّي البراءة كصدمة طفولية (trauma obscures innocence) :contentReference[oaicite:3]{index=3}"]'::jsonb, '["لحظة طفولية بحتة مليانة دهشة بدون توقع","تفاعل صادق دون تكلف أو مصلحة","لحظة صمت تتلوها ضحكة صافية أو نظرة ناصعة","رؤية طاهر أو تجربة تؤثر بلا تعقيد","انخراط في نشاط يُحرّر من التفكير السلبي"]'::jsonb, '[]'::jsonb, '{"english_name":"Innocence","type":"أساسي"}'::jsonb)
ON CONFLICT (emotion_key) DO UPDATE SET arabic_name = EXCLUDED.arabic_name, category = EXCLUDED.category, definition = EXCLUDED.definition, body_sensations = EXCLUDED.body_sensations, triggers = EXCLUDED.triggers, healthy_expressions = EXCLUDED.healthy_expressions, metadata = EXCLUDED.metadata;
INSERT INTO public.emotions_encyclopedia (id, emotion_key, arabic_name, category, intensity_level, definition, body_sensations, triggers, healthy_expressions, metadata)
VALUES ('20000000-0000-0000-0000-000000000052', 'sadness', 'حزن', 'عاطفي / نفسي / اجتماعي', 2, 'شعور ألم نفسي نابع من الخسارة أو الافتقاد أو الإحباط، يرافقه انخفاض في النشاط العاطفي والطاقة لفترة مؤقتة.', '["انخفاض النشاط والطاقة، مشية بطيئة ومنحنية :contentReference[oaicite:1]{index=1}","خفقان القلب وتسارع التنفس في الحالات الشديدة :contentReference[oaicite:2]{index=2}","اضطرابات النوم والمعدة والتغيّرات في الوزن :contentReference[oaicite:3]{index=3}","ضعف المناعة وزيادة احتمالية الأمراض المزمنة :contentReference[oaicite:4]{index=4}","ألم صدري أو ضغط في الجسم مرتبط باضطراب الجهاز العصبي المستمر :contentReference[oaicite:5]{index=5}"]'::jsonb, '["فقدان شخص عزيز أو نهاية علاقة","إحباط شديد أو خيبة أمل كبيرة","ذكريات مؤلمة تلامس القلب","مشهد محزن أو خبر مؤثر","شعور بالعجز أمام ظروف خارجة عن السيطرة"]'::jsonb, '[]'::jsonb, '{"english_name":"Sadness","type":"أساسي"}'::jsonb)
ON CONFLICT (emotion_key) DO UPDATE SET arabic_name = EXCLUDED.arabic_name, category = EXCLUDED.category, definition = EXCLUDED.definition, body_sensations = EXCLUDED.body_sensations, triggers = EXCLUDED.triggers, healthy_expressions = EXCLUDED.healthy_expressions, metadata = EXCLUDED.metadata;
INSERT INTO public.emotions_encyclopedia (id, emotion_key, arabic_name, category, intensity_level, definition, body_sensations, triggers, healthy_expressions, metadata)
VALUES ('20000000-0000-0000-0000-000000000053', 'fear', 'خوف', 'عاطفي / بقاء / رد فعل أولي', 2, 'استجابة فطرية لخطر متصور أو حقيقي، تهدف لحماية الذات بسرعة عبر تحفيز نظام الـ fight‑or‑flight.', '["زيادة ضربات القلب وضغط الدم بسبب الأدرينالين والكورتيزول :contentReference[oaicite:1]{index=1}","تنفس سريع وشعور بالتعرق :contentReference[oaicite:2]{index=2}","ارتجاف عضلي (trembling) وتحضير عضلات الجسد ْ:contentReference[oaicite:3]{index=3}"]'::jsonb, '["رؤية أو سماع خطر مفاجئ","تجربة سابقة مشابهة (conditioning)","استدعاء ذاكري لموقف مخيف","عدم اليقين أو شعور بالخطر"]'::jsonb, '[]'::jsonb, '{"english_name":"Fear","type":"أساسي"}'::jsonb)
ON CONFLICT (emotion_key) DO UPDATE SET arabic_name = EXCLUDED.arabic_name, category = EXCLUDED.category, definition = EXCLUDED.definition, body_sensations = EXCLUDED.body_sensations, triggers = EXCLUDED.triggers, healthy_expressions = EXCLUDED.healthy_expressions, metadata = EXCLUDED.metadata;
INSERT INTO public.emotions_encyclopedia (id, emotion_key, arabic_name, category, intensity_level, definition, body_sensations, triggers, healthy_expressions, metadata)
VALUES ('20000000-0000-0000-0000-000000000054', 'anger', 'غضب', 'عاطفي / بقاء / رد فعل أولي', 2, 'استجابة قوية لفعل يُعد تهديداً أو غير عادل، تدفع لاتخاذ إجراء (مواجهة أو حماية) بفعل تحفيز فطري.', '["ارتفاع ضغط الدم ومعدل ضربات القلب بسبب الأدرينالين والكورتيزول :contentReference[oaicite:1]{index=1}","تنفُّس سريع، تعرّق، واحمرار الوجه ضمن استجابة fight‑or‑flight :contentReference[oaicite:2]{index=2}","ارتجاف عضلي، شدّ في الجسم، وتجهيز للرد أو المواجهة :contentReference[oaicite:3]{index=3}","إطلاق مواد التهابية على المدى الطويل ترتبط بأمراض القلب والضغط :contentReference[oaicite:4]{index=4}"]'::jsonb, '["شعور بالظلم أو الخيانة","تهديد للذات أو الموارد","إحباط مستمر لأهداف مهمة","تذكّر موقف جارح من الماضي","تعرض لإهانة أو استفزاز"]'::jsonb, '[]'::jsonb, '{"english_name":"Anger","type":"أساسي"}'::jsonb)
ON CONFLICT (emotion_key) DO UPDATE SET arabic_name = EXCLUDED.arabic_name, category = EXCLUDED.category, definition = EXCLUDED.definition, body_sensations = EXCLUDED.body_sensations, triggers = EXCLUDED.triggers, healthy_expressions = EXCLUDED.healthy_expressions, metadata = EXCLUDED.metadata;
INSERT INTO public.emotions_encyclopedia (id, emotion_key, arabic_name, category, intensity_level, definition, body_sensations, triggers, healthy_expressions, metadata)
VALUES ('20000000-0000-0000-0000-000000000055', 'guilt', 'ذنب', 'عاطفي / اجتماعي / أخلاقي', 2, 'شعور سلبي ينشأ عندما يعتقد الشخص أنه انتهك معياراً أخلاقياً أو أساء للآخر، ويدفعه للإصلاح أو التعويض.', '["نشاط الجهاز العصبي السمبثاوي – خفقان، تعرّق :contentReference[oaicite:1]{index=1}","تنفّس متغيّر وانخفاض حرارة الجلد (vasoconstriction) :contentReference[oaicite:2]{index=2}","إحساس بالتوتر الجسدي وعضلات مشدودة أو تقلصات"]'::jsonb, '["ارتكاب خطأ بحق شخص أو تجاه معيار داخلي","التذكّر بفعل سلبي أو قرار خاطئ","معرفة أن الفعل تسبب بأذى للآخر","مواجهتك بتصرفك أمام مجتمع أو شخص محبّ"]'::jsonb, '[]'::jsonb, '{"english_name":"Guilt","type":"أساسي"}'::jsonb)
ON CONFLICT (emotion_key) DO UPDATE SET arabic_name = EXCLUDED.arabic_name, category = EXCLUDED.category, definition = EXCLUDED.definition, body_sensations = EXCLUDED.body_sensations, triggers = EXCLUDED.triggers, healthy_expressions = EXCLUDED.healthy_expressions, metadata = EXCLUDED.metadata;
INSERT INTO public.emotions_encyclopedia (id, emotion_key, arabic_name, category, intensity_level, definition, body_sensations, triggers, healthy_expressions, metadata)
VALUES ('20000000-0000-0000-0000-000000000056', 'embarrassment', 'خجل', 'عاطفي / اجتماعي / انفعالي', 2, 'شعور بتوتر ووعي بالذات عند ارتكاب خطأ اجتماعي بسيط أو انكشاف نقص أمام الآخرين، يكون قصيرًا ويحفّز الإصلاح الاجتماعي.', '["احمرار الوجه","خفقان القلب والتنفس السريع","ميل للاختباء أو إخفاء الرأس"]'::jsonb, '["ارتكاب خطأ صغير أمام الغرباء أو الأصدقاء","نظرات الآخرين تشعرك بالإحراج","نسيان اسم شخص معروف أمامه","سقطة بسيطة أو حراك محرج في مكان عام"]'::jsonb, '[]'::jsonb, '{"english_name":"Embarrassment","type":"فرعي"}'::jsonb)
ON CONFLICT (emotion_key) DO UPDATE SET arabic_name = EXCLUDED.arabic_name, category = EXCLUDED.category, definition = EXCLUDED.definition, body_sensations = EXCLUDED.body_sensations, triggers = EXCLUDED.triggers, healthy_expressions = EXCLUDED.healthy_expressions, metadata = EXCLUDED.metadata;
INSERT INTO public.emotions_encyclopedia (id, emotion_key, arabic_name, category, intensity_level, definition, body_sensations, triggers, healthy_expressions, metadata)
VALUES ('20000000-0000-0000-0000-000000000057', 'shame', 'عار', 'عاطفي / اجتماعي / هوية', 2, 'شعور عميق بالذنب أو الانكشاف الجوهري، يرتبط بإحساس أن الذات بأكملها معيبة أمام الآخرين، يدفع للانسحاب أو الدفاع عن النفس.', '["إحساس بالتجمد أو الاختفاء","الكتفين منحنيان ونظرة لأسفل","خفقان القلب مستمر دون راحة"]'::jsonb, '["مخالفة خطيرة لمعايير أخلاقية أو اجتماعية","استنكار واضح أو لوم علني","فشل كبير أمام المجتمع","كشف عيب داخلي أو سلوك غير مقبول"]'::jsonb, '[]'::jsonb, '{"english_name":"Shame","type":"فرعي"}'::jsonb)
ON CONFLICT (emotion_key) DO UPDATE SET arabic_name = EXCLUDED.arabic_name, category = EXCLUDED.category, definition = EXCLUDED.definition, body_sensations = EXCLUDED.body_sensations, triggers = EXCLUDED.triggers, healthy_expressions = EXCLUDED.healthy_expressions, metadata = EXCLUDED.metadata;
INSERT INTO public.emotions_encyclopedia (id, emotion_key, arabic_name, category, intensity_level, definition, body_sensations, triggers, healthy_expressions, metadata)
VALUES ('20000000-0000-0000-0000-000000000058', 'disgust', 'اشمئزاز', 'عاطفي / بقاء / تجنب', 2, 'استجابة فردية نفور ورفض تجاه شيء ملوث أو منحرف، يهدف لحماية الجسم من العدوى أو الانفصال عن مصادر غير مرغوب فيها.', '["غثيان ورغبة في القيء :contentReference[oaicite:1]{index=1}","تباطؤ ضربات القلب أحيانًا (core disgust) :contentReference[oaicite:2]{index=2}","تقلص حاد في عضلات الوجه: أنف مجعد، شفاه مشدودة، جفنين مضمومين :contentReference[oaicite:3]{index=3}","اضطرابات في الإيعاء المعوي (اختلالات كهربائية في المعدة) :contentReference[oaicite:4]{index=4}"]'::jsonb, '["مواد فاسدة أو أكلك دائمة النفُور (عفونة، قيء، دم)","انتهاك للحدود الجسدية (جروح/جسد مكشوف)","أفعال أخلاقية منافية للطبع (خداع، قسوة)","رؤية شخص يتقيأ أو يُصاب بمرض"]'::jsonb, '[]'::jsonb, '{"english_name":"Disgust","type":"أساسي"}'::jsonb)
ON CONFLICT (emotion_key) DO UPDATE SET arabic_name = EXCLUDED.arabic_name, category = EXCLUDED.category, definition = EXCLUDED.definition, body_sensations = EXCLUDED.body_sensations, triggers = EXCLUDED.triggers, healthy_expressions = EXCLUDED.healthy_expressions, metadata = EXCLUDED.metadata;
INSERT INTO public.emotions_encyclopedia (id, emotion_key, arabic_name, category, intensity_level, definition, body_sensations, triggers, healthy_expressions, metadata)
VALUES ('20000000-0000-0000-0000-000000000059', 'envy-jealousy', 'غيرة', 'عاطفي / اجتماعي / إدراكي', 2, 'شعور بالاستياء أو الانزعاج تجاه وضع شخص آخر يملك ما يفتقر إليه الفرد (envy)، أو خوف من فقدان ما يملكه لصالح شخص ثالث (jealousy).', '["توتر جسدي واضح – خفقان القلب وتعرق :contentReference[oaicite:1]{index=1}","تشنّج عضلي أو ارتجاف خفيف نتيجة الضغط النفسي","احمرار الوجه أحيانًا كعلامة فورية"]'::jsonb, '["رؤية شخص يمتلك ما نرغب به","خوف من فقدان علاقة أو مركز مهم (jealousy)","ملاحظة تفوق الآخرين في مجالات نراها مهمة","الشعور بأن الآخرين يتلقون تقدير أكثر منا"]'::jsonb, '[]'::jsonb, '{"english_name":"Envy / Jealousy","type":"أساسي"}'::jsonb)
ON CONFLICT (emotion_key) DO UPDATE SET arabic_name = EXCLUDED.arabic_name, category = EXCLUDED.category, definition = EXCLUDED.definition, body_sensations = EXCLUDED.body_sensations, triggers = EXCLUDED.triggers, healthy_expressions = EXCLUDED.healthy_expressions, metadata = EXCLUDED.metadata;
INSERT INTO public.emotions_encyclopedia (id, emotion_key, arabic_name, category, intensity_level, definition, body_sensations, triggers, healthy_expressions, metadata)
VALUES ('20000000-0000-0000-0000-000000000060', 'envy', 'حسد', 'عاطفي / اجتماعي / إدراكي', 2, 'شعور مؤلم بالاستياء أو الغيرة تجاه شخص يمتلك شيئًا نرغب به، يتراوح بين تحفيز إيجابي لتطوير الذات ورفض سلبي يضر بالعلاقات.', '["توتر عام وخفقان حرارة في الجسم :contentReference[oaicite:2]{index=2}","تعرّق أو ارتعاش خفيف","احمرار أحيانًا كدلالة على الانفعال العاطفي"]'::jsonb, '["رؤية شخص يملك ما نرغب فيه (نجاح، مال، موهبة) :contentReference[oaicite:1]{index=1}","الشعور بأن الآخر لا يستحق الأفضل منه","كتابة أو تذكّر إنجازاته أمامنا بشكل متكرر","المقارنة الدائمة داخل بيئة تنافسية"]'::jsonb, '[]'::jsonb, '{"english_name":"Envy","type":"أساسي"}'::jsonb)
ON CONFLICT (emotion_key) DO UPDATE SET arabic_name = EXCLUDED.arabic_name, category = EXCLUDED.category, definition = EXCLUDED.definition, body_sensations = EXCLUDED.body_sensations, triggers = EXCLUDED.triggers, healthy_expressions = EXCLUDED.healthy_expressions, metadata = EXCLUDED.metadata;
INSERT INTO public.emotions_encyclopedia (id, emotion_key, arabic_name, category, intensity_level, definition, body_sensations, triggers, healthy_expressions, metadata)
VALUES ('20000000-0000-0000-0000-000000000061', 'resentment-displeasure', 'استياء', 'عاطفي / اجتماعي / تنظيمي', 2, 'شعور سلبي يخطّره الاستياء أو الانزعاج عميق من موقف أو تصرف، يتضمّن ألمًا عاطفيًا دفينًا أحيانًا وميولًا للعدائية أو التجمّد.', '["خفقان قلب وتعب جسدي، رغم كبح الفعل الظاهر :contentReference[oaicite:1]{index=1}","نشاط متبادَل في الجهاز العصبي: sympathetic للانزعاج، parasympathetic لكبح الفعل :contentReference[oaicite:2]{index=2}"]'::jsonb, '["تجارب متكرّرة من الظلم أو الإهمال","التذكّر المستمر للخطأ الذي ترك أثرًا مؤلمًا","عدم الحصول على تعويض أو تقدير بعد جرح عاطفي"]'::jsonb, '[]'::jsonb, '{"english_name":"Resentment/Displeasure","type":"مركب"}'::jsonb)
ON CONFLICT (emotion_key) DO UPDATE SET arabic_name = EXCLUDED.arabic_name, category = EXCLUDED.category, definition = EXCLUDED.definition, body_sensations = EXCLUDED.body_sensations, triggers = EXCLUDED.triggers, healthy_expressions = EXCLUDED.healthy_expressions, metadata = EXCLUDED.metadata;
INSERT INTO public.emotions_encyclopedia (id, emotion_key, arabic_name, category, intensity_level, definition, body_sensations, triggers, healthy_expressions, metadata)
VALUES ('20000000-0000-0000-0000-000000000062', 'loneliness', 'وحده', 'عاطفي / اجتماعي / بقاء', 2, 'شعور نفسي نارٍ بالنقص في التواصل والعلاقات رغم وجود الناس، يُشعرك بخُرقة داخلية وأنك منفصل حتى وسط الجموع.', '["زيادة الكورتيزول والتوتر المزمن – مثل التدخين من ناحية الضرر :contentReference[oaicite:3]{index=3}","ضعف الجهاز المناعي وزيادة الالتهاب :contentReference[oaicite:4]{index=4}","اضطرابات النوم وحدوث كوابيس متكررة :contentReference[oaicite:5]{index=5}","انخفاض حرارة الجلد المحيطي – تضييق الأوعية (vasoconstriction) :contentReference[oaicite:6]{index=6}"]'::jsonb, '["غياب علاقات ذات معنى أو عمق عاطفي :contentReference[oaicite:1]{index=1}","فقدان شخص أو تغيير جذري في الحياة","التواجد وسط ناس لكن بدون مشاهدة قربهم الحقيقية :contentReference[oaicite:2]{index=2}","قيمة الاهتمام الذاتي المنخفضة أو الانطواء الاجتماعي"]'::jsonb, '[]'::jsonb, '{"english_name":"Loneliness","type":"أساسي"}'::jsonb)
ON CONFLICT (emotion_key) DO UPDATE SET arabic_name = EXCLUDED.arabic_name, category = EXCLUDED.category, definition = EXCLUDED.definition, body_sensations = EXCLUDED.body_sensations, triggers = EXCLUDED.triggers, healthy_expressions = EXCLUDED.healthy_expressions, metadata = EXCLUDED.metadata;
INSERT INTO public.emotions_encyclopedia (id, emotion_key, arabic_name, category, intensity_level, definition, body_sensations, triggers, healthy_expressions, metadata)
VALUES ('20000000-0000-0000-0000-000000000063', 'insecurity', 'انعدام الأمان', 'نفسي / اجتماعي / بقاء', 2, 'شعور داخلي بعدم الثقة بالنفس أو بالبيئة المحيطة، يصاحبه قلق وتذبذب في التقدير الذاتي وسلوكيات دفاعية أو تجنبية.', '["توتر عام مع خفقان قلب وتعرّق :contentReference[oaicite:1]{index=1}","اضطرابات في النوم، هرمونات الإجهاد، وتهدّل نفسي جسدي :contentReference[oaicite:2]{index=2}","أعراض جسدية غامضة (حقًا مرتبطة بـ somatization) :contentReference[oaicite:3]{index=3}"]'::jsonb, '["قصور في التجارب الإيجابية الذاتية","تجارب طفولة مرتبطة بتثبيط أو رفض","مقارنة اجتماعية مستمرة أو ضغوط شخصية","أحداث تهاجم القدرة أو التقدير الذاتي"]'::jsonb, '[]'::jsonb, '{"english_name":"Insecurity","type":"أساسي"}'::jsonb)
ON CONFLICT (emotion_key) DO UPDATE SET arabic_name = EXCLUDED.arabic_name, category = EXCLUDED.category, definition = EXCLUDED.definition, body_sensations = EXCLUDED.body_sensations, triggers = EXCLUDED.triggers, healthy_expressions = EXCLUDED.healthy_expressions, metadata = EXCLUDED.metadata;
INSERT INTO public.emotions_encyclopedia (id, emotion_key, arabic_name, category, intensity_level, definition, body_sensations, triggers, healthy_expressions, metadata)
VALUES ('20000000-0000-0000-0000-000000000064', 'frustration', 'إحباط', 'عاطفي / بقاء / إدراكي', 2, 'شعور سلبي ينتج عند منع تحقيق هدف مهم رغم الجهد المبذول، يرافقه انفعال وعدم رضى يصل أحياناً للغضب أو الاستسلام.', '["ارتفاع الكورتيزول والأدرينالين → خفقان ضغط وتنفس سريع :contentReference[oaicite:3]{index=3}","توتر عضلي عام ونفسية ''مشدودة'' مستواها بيتغير مع الغضب أو الاستسلام","إرهاق ذهني وتقليل الطاقة – تؤثر على التحمّل الجسدي"]'::jsonb, '["عدم الوصول لهدف حتى مع المحاولة المتكررة :contentReference[oaicite:1]{index=1}","مؤخرات غير مبررة في الحصول على حق أو إنجاز ما :contentReference[oaicite:2]{index=2}","مقاومة أو منع خارجي أو داخلي مستمر رغم الرغبة"]'::jsonb, '[]'::jsonb, '{"english_name":"Frustration","type":"أساسي"}'::jsonb)
ON CONFLICT (emotion_key) DO UPDATE SET arabic_name = EXCLUDED.arabic_name, category = EXCLUDED.category, definition = EXCLUDED.definition, body_sensations = EXCLUDED.body_sensations, triggers = EXCLUDED.triggers, healthy_expressions = EXCLUDED.healthy_expressions, metadata = EXCLUDED.metadata;
INSERT INTO public.emotions_encyclopedia (id, emotion_key, arabic_name, category, intensity_level, definition, body_sensations, triggers, healthy_expressions, metadata)
VALUES ('20000000-0000-0000-0000-000000000065', 'disappointment', 'خيبة أمل', 'عاطفي / معرفي / توقعات', 2, 'شعور سلبي ينشأ عند عدم تحقيق توقع كانت تأملها النفس أو الأمل، حيث ينكسر التوازن بين ما أنتظرت وما حدث بالفعل.', '["انخفاض في الدوبامين والسيروتونين – شعور ’كرّبة‘ مؤلمة :contentReference[oaicite:4]{index=4}","توتر عضلي، صداع، تعب نفسي يشبه الجراح العاطفية :contentReference[oaicite:5]{index=5}","إرهاق ونعاس مصاحب لضغط عاطفي مستمر :contentReference[oaicite:6]{index=6}"]'::jsonb, '["عدم تحقيق هدف مهم رغم الجهد :contentReference[oaicite:1]{index=1}","نتيجة أدت إلى فجوة كبيرة بين ما توقعت وما حصل :contentReference[oaicite:2]{index=2}","وعد لم يُوفى به من شخص مقرب :contentReference[oaicite:3]{index=3}"]'::jsonb, '[]'::jsonb, '{"english_name":"Disappointment","type":"أساسي"}'::jsonb)
ON CONFLICT (emotion_key) DO UPDATE SET arabic_name = EXCLUDED.arabic_name, category = EXCLUDED.category, definition = EXCLUDED.definition, body_sensations = EXCLUDED.body_sensations, triggers = EXCLUDED.triggers, healthy_expressions = EXCLUDED.healthy_expressions, metadata = EXCLUDED.metadata;
INSERT INTO public.emotions_encyclopedia (id, emotion_key, arabic_name, category, intensity_level, definition, body_sensations, triggers, healthy_expressions, metadata)
VALUES ('20000000-0000-0000-0000-000000000066', 'terror', 'رعب', 'عاطفي / بقاء / ردة فعل حادة ومكثفة', 2, 'خوف فائق يتجاوز الحاجز المنطقي، يجعل العقل مؤمّن تلقائياً، يستولي على الجسم والعقل.', '["تجمّد كامل (freeze)","ارتجاف أو فقدان القدرة على الحركة","تشبّع التنفس/خفقان حاد"]'::jsonb, '["خطر فوري وشديد – تهديد للحياة (مثل هجوم مباشر)","الضغط الداخلي – حس اختناق أو رائحة الغاز"]'::jsonb, '[]'::jsonb, '{"english_name":"Terror","type":"فرعي / مَكثّف من الخوف"}'::jsonb)
ON CONFLICT (emotion_key) DO UPDATE SET arabic_name = EXCLUDED.arabic_name, category = EXCLUDED.category, definition = EXCLUDED.definition, body_sensations = EXCLUDED.body_sensations, triggers = EXCLUDED.triggers, healthy_expressions = EXCLUDED.healthy_expressions, metadata = EXCLUDED.metadata;
INSERT INTO public.emotions_encyclopedia (id, emotion_key, arabic_name, category, intensity_level, definition, body_sensations, triggers, healthy_expressions, metadata)
VALUES ('20000000-0000-0000-0000-000000000067', 'anxiety', 'قلق', 'عاطفي / بقاء / معرفي', 2, 'ردّة فعل عاطفية ونفسية تجاه خطر محتمل أو توقع سلبي، تشمل استجابة جسدية ونشاط دماغي مستمر حتى بدون تهديد حقيقي.', '["خفقان القلب وارتفاع ضغط الدم :contentReference[oaicite:1]{index=1}","تنفّس سريع وضيق بالنفس (hyperventilation) :contentReference[oaicite:2]{index=2}","توتر عضلي، صداع، اضطرابات هضمية وأرق :contentReference[oaicite:3]{index=3}","تعب مستمر ومناعة ضعيفة نتيجة الكورتيزول عالي المزمن :contentReference[oaicite:4]{index=4}"]'::jsonb, '["توقع تهديد مستمر أو عدم اليقين","توتر أو ضغط متكرر في الحياة أو العمل","ذكريات مؤلمة تُحرّض الاستجابة الخوفية","إيقاع حياة سريع دون فرصة للراحة"]'::jsonb, '[]'::jsonb, '{"english_name":"Anxiety","type":"أساسي"}'::jsonb)
ON CONFLICT (emotion_key) DO UPDATE SET arabic_name = EXCLUDED.arabic_name, category = EXCLUDED.category, definition = EXCLUDED.definition, body_sensations = EXCLUDED.body_sensations, triggers = EXCLUDED.triggers, healthy_expressions = EXCLUDED.healthy_expressions, metadata = EXCLUDED.metadata;
INSERT INTO public.emotions_encyclopedia (id, emotion_key, arabic_name, category, intensity_level, definition, body_sensations, triggers, healthy_expressions, metadata)
VALUES ('20000000-0000-0000-0000-000000000068', 'bitterness-embitterment', 'مرارة', 'عاطفي / اجتماعي / إدراكي', 2, 'شعور حاد بالاستياء والغضب والظلم يدوم بعد تجربة جارحة، يحمل دفاءً من الخيبة وقد يتحوّل إلى حالة عصابية إذا استمرّ.', '["زيادة الكورتيزول → ضغط وتوتر عام :contentReference[oaicite:1]{index=1}","تشنجات عضلية وصداع وصعوبة في النوم نتيجة التفكير المتكرر","ضعف المناعة والتعب المنتظم"]'::jsonb, '["خسارة أو طعنة اجتماعية مؤلمة","مواقف اعتداء أو جرح العزة","انتهاك الثقة من أشخاص عزيزين","فشل في تدارك حق أو عدالة متوقعة"]'::jsonb, '[]'::jsonb, '{"english_name":"Bitterness / Embitterment","type":"مركب"}'::jsonb)
ON CONFLICT (emotion_key) DO UPDATE SET arabic_name = EXCLUDED.arabic_name, category = EXCLUDED.category, definition = EXCLUDED.definition, body_sensations = EXCLUDED.body_sensations, triggers = EXCLUDED.triggers, healthy_expressions = EXCLUDED.healthy_expressions, metadata = EXCLUDED.metadata;
INSERT INTO public.emotions_encyclopedia (id, emotion_key, arabic_name, category, intensity_level, definition, body_sensations, triggers, healthy_expressions, metadata)
VALUES ('20000000-0000-0000-0000-000000000069', 'embarrassment', 'إحراج', 'عاطفي / اجتماعي / انفعالي', 2, 'شعور مؤقت من الخجل والقلق الناتج عن انتهاك قاعدة اجتماعية أو ارتكاب خطأ أمام الآخرين، يستدعي الانسحاب أو التصحيح السريع.', '["احمرار الوجه (blushing) – تدفق دم مرتبط بالتعرض الاجتماعي :contentReference[oaicite:3]{index=3}","خفقان القلب وارتفاع ضغط الدم مع تباطؤ لاحق – نمط مميز للإحراج :contentReference[oaicite:4]{index=4}","تعرّق، رعشة، وتململ (fidgeting) :contentReference[oaicite:5]{index=5}"]'::jsonb, '["سقطة أو خطأ أمام الغرباء أو الأصدقاء :contentReference[oaicite:1]{index=1}","انكشاف عيب جسدي أو وظيفي أمام الجمهور :contentReference[oaicite:2]{index=2}","شعور بأن الآخرين يحكمون عليك"]'::jsonb, '[]'::jsonb, '{"english_name":"Embarrassment","type":"فرعي"}'::jsonb)
ON CONFLICT (emotion_key) DO UPDATE SET arabic_name = EXCLUDED.arabic_name, category = EXCLUDED.category, definition = EXCLUDED.definition, body_sensations = EXCLUDED.body_sensations, triggers = EXCLUDED.triggers, healthy_expressions = EXCLUDED.healthy_expressions, metadata = EXCLUDED.metadata;
INSERT INTO public.emotions_encyclopedia (id, emotion_key, arabic_name, category, intensity_level, definition, body_sensations, triggers, healthy_expressions, metadata)
VALUES ('20000000-0000-0000-0000-000000000070', 'emotional-abandonment', 'تخلي', 'عاطفي / اجتماعي / بقاء', 2, 'إحساس مؤلم بعدم وجود شخص مهم بجانبك، رغم حاجتك له، ويترافق مع شعور بالرفض، الخذلان، وأحيانًا الشعور بأنك غير مرغوب فيه.', '["ارتفاع الكورتيزول والتوتر المزمن مشابه للاكتئاب :contentReference[oaicite:2]{index=2}","اضطرابات في النوم والمناعة نتيجة الشعور بالعزلة :contentReference[oaicite:3]{index=3}","توتر عضلي وشعور بالخناق الخفي – ارتباط مباشر بالخوف من الانفصال"]'::jsonb, '["غياب الحبيب فجأة أو بعدم اهتمام","فراق مفاجئ أو رحيل دون مبرر واضح :contentReference[oaicite:1]{index=1}","تكرار الإهمال العاطفي من شخص مقرب","انقطاع مفاجئ في التواصل أو دعم معنوي"]'::jsonb, '[]'::jsonb, '{"english_name":"Emotional Abandonment","type":"مركب"}'::jsonb)
ON CONFLICT (emotion_key) DO UPDATE SET arabic_name = EXCLUDED.arabic_name, category = EXCLUDED.category, definition = EXCLUDED.definition, body_sensations = EXCLUDED.body_sensations, triggers = EXCLUDED.triggers, healthy_expressions = EXCLUDED.healthy_expressions, metadata = EXCLUDED.metadata;
INSERT INTO public.emotions_encyclopedia (id, emotion_key, arabic_name, category, intensity_level, definition, body_sensations, triggers, healthy_expressions, metadata)
VALUES ('20000000-0000-0000-0000-000000000071', 'loneliness-social-isolation', 'عزلة', 'اجتماعي / نفسي / صحي', 2, 'شعور بالانفصال أو الوحدة رغم إمكانية وجود الناس، وقد يتحول إلى حالة صحية خطيرة إذا طال، مستمر لفترة غير مرغوب بها.', '["زيادة الكورتيزول والتوتر المزمن – ضعف مناعة وأمراض مزمنة :contentReference[oaicite:4]{index=4}","ارتفاع ضغط الدم وأمراض القلب والسكتات – مخاطر صحية تضاهي التبغ :contentReference[oaicite:5]{index=5}","اضطرابات النوم، تعب دائم، صداع ومناعة ضعيفة :contentReference[oaicite:6]{index=6}"]'::jsonb, '["قلة الأصدقاء أو فقدان شخص مقرب :contentReference[oaicite:1]{index=1}","تغيّرات كبيرة في الحياة—فتور علاقات، انتقال، طلاق","قلق أو اكتئاب يؤدي للانسحاب الاجتماعي :contentReference[oaicite:2]{index=2}","الاعتماد على التواصل الرقمي بدل العلاقات الواقعية :contentReference[oaicite:3]{index=3}"]'::jsonb, '[]'::jsonb, '{"english_name":"Loneliness / Social Isolation","type":"أساسي"}'::jsonb)
ON CONFLICT (emotion_key) DO UPDATE SET arabic_name = EXCLUDED.arabic_name, category = EXCLUDED.category, definition = EXCLUDED.definition, body_sensations = EXCLUDED.body_sensations, triggers = EXCLUDED.triggers, healthy_expressions = EXCLUDED.healthy_expressions, metadata = EXCLUDED.metadata;
INSERT INTO public.emotions_encyclopedia (id, emotion_key, arabic_name, category, intensity_level, definition, body_sensations, triggers, healthy_expressions, metadata)
VALUES ('20000000-0000-0000-0000-000000000072', 'low-self-worth', 'انعدام القيمة', 'نفسي / اجتماعي / إدراكي', 2, 'شعور داخلي بعدم كفاية الذات، ينبع من مقارنة مستمرة، صعوبات في استيعاب الثناء، وخوف دائم من الرفض، يؤثر على الصحة النفسية والعلاقات.', '["خفقان القلب، توتر عضلي، اضطراب النوم نتيجة التوتر المزمن :contentReference[oaicite:2]{index=2}","زيادة الكورتيزول ونشاط الجهاز العصبي السمبثاوي"]'::jsonb, '["تعليقات نقدية أو مواقف تُشعر بالنقص","المقارنات الاجتماعية المتكررة :contentReference[oaicite:1]{index=1}","التجارب الطفولية النقدية أو الإهمال","فشل ظاهر ينعكس على تقدير الذات"]'::jsonb, '[]'::jsonb, '{"english_name":"Low Self‑Worth","type":"أساسي"}'::jsonb)
ON CONFLICT (emotion_key) DO UPDATE SET arabic_name = EXCLUDED.arabic_name, category = EXCLUDED.category, definition = EXCLUDED.definition, body_sensations = EXCLUDED.body_sensations, triggers = EXCLUDED.triggers, healthy_expressions = EXCLUDED.healthy_expressions, metadata = EXCLUDED.metadata;
INSERT INTO public.emotions_encyclopedia (id, emotion_key, arabic_name, category, intensity_level, definition, body_sensations, triggers, healthy_expressions, metadata)
VALUES ('20000000-0000-0000-0000-000000000073', 'helplessness-learned-helplessness', 'عجز', 'عاطفي / بقاء / إدراكي', 2, 'شعور بفقدان القدرة على التأثير على الواقع بعد تجارب متكررة من الفشل أو الحرمان من التحكم، يؤدي إلى استسلام سلبي وإحباط عام.', '["تثبيط الحركة والتراخي العضلي – إرهاق دائم","ارتفاع الكورتيزول واضطراب النوم والهضم نتيجة المحفز المزمن :contentReference[oaicite:2]{index=2}","خفض المناعة وزيادة الحساسية للأمراض"]'::jsonb, '["تكرار فشل متوقع (مثل محاضرات رياضيات أو مواقف مهنية) :contentReference[oaicite:1]{index=1}","ضغوط لا يمكن التحكم فيها—إهمال، صدمات نفسية، بيئة صارمة","تفكير سلبي نمطي: ''مش هينفع'' أو تفسير مرضي للفشل"]'::jsonb, '[]'::jsonb, '{"english_name":"Helplessness / Learned Helplessness","type":"أساسي"}'::jsonb)
ON CONFLICT (emotion_key) DO UPDATE SET arabic_name = EXCLUDED.arabic_name, category = EXCLUDED.category, definition = EXCLUDED.definition, body_sensations = EXCLUDED.body_sensations, triggers = EXCLUDED.triggers, healthy_expressions = EXCLUDED.healthy_expressions, metadata = EXCLUDED.metadata;
INSERT INTO public.emotions_encyclopedia (id, emotion_key, arabic_name, category, intensity_level, definition, body_sensations, triggers, healthy_expressions, metadata)
VALUES ('20000000-0000-0000-0000-000000000074', 'regret', 'ندم', 'عاطفي / معرفي / اجتماعي', 2, 'شعور سلبي ناتج عن التفكير في ما كان يمكن أن يكون مختلفًا إذا تم اتخاذ قرار آخر؛ يجمع بين ألم وعاطفة وقراءة ذهنية (counterfactual).', '["زيادة التوتر وضغط الدم نتيجة التفكير المتكرر (perseverative cognition) :contentReference[oaicite:4]{index=4}","إفراز الكورتيزول والأدرينالين وطاقة سلبية مستمرة :contentReference[oaicite:5]{index=5}","أرق، صداع، تعب عاطفي يدوم أيام أو شهور :contentReference[oaicite:6]{index=6}"]'::jsonb, '["قرار خاطئ أدى لنتيجة أسوأ مقارنة بخيار آخر :contentReference[oaicite:1]{index=1}","التردد في اتخاذ قرار وعدم اختيار أي خيار (ندم على عدم الفعل) :contentReference[oaicite:2]{index=2}","مفاجآت تُظهر أن الخيار الآخر كان أفضل (feedback) :contentReference[oaicite:3]{index=3}"]'::jsonb, '[]'::jsonb, '{"english_name":"Regret","type":"أساسي"}'::jsonb)
ON CONFLICT (emotion_key) DO UPDATE SET arabic_name = EXCLUDED.arabic_name, category = EXCLUDED.category, definition = EXCLUDED.definition, body_sensations = EXCLUDED.body_sensations, triggers = EXCLUDED.triggers, healthy_expressions = EXCLUDED.healthy_expressions, metadata = EXCLUDED.metadata;
INSERT INTO public.emotions_encyclopedia (id, emotion_key, arabic_name, category, intensity_level, definition, body_sensations, triggers, healthy_expressions, metadata)
VALUES ('20000000-0000-0000-0000-000000000075', 'self-hatred', 'كراهية الذات', 'عاطفي / نفسي / اجتماعي', 2, 'إحساس داخلي قوي بالرفض والاشمئزاز من الذات، مرتبط بنقد ذاتي لاذع وشعور عميق بعدم الجدارة، قد يقود لأذى أو تفاقم مشاكل نفسية.', '["توتر عضلي، صداع، اضطرابات في الهضم والنوم :contentReference[oaicite:4]{index=4}","ارتفاع الكورتيزول وتوتر دائم يعزز التعب والصحة الضعيفة :contentReference[oaicite:5]{index=5}"]'::jsonb, '["أفكار سلبية متكررة عن النفس","مقارنات اجتماعية وانتقادات داخلية مستمرة :contentReference[oaicite:1]{index=1}","تجارب صادمة أو رفض من الأسرة في الطفولة :contentReference[oaicite:2]{index=2}","المعايير المجتمعية العالية والكمالية غير الواقعية :contentReference[oaicite:3]{index=3}"]'::jsonb, '[]'::jsonb, '{"english_name":"Self-Hatred","type":"أساسي"}'::jsonb)
ON CONFLICT (emotion_key) DO UPDATE SET arabic_name = EXCLUDED.arabic_name, category = EXCLUDED.category, definition = EXCLUDED.definition, body_sensations = EXCLUDED.body_sensations, triggers = EXCLUDED.triggers, healthy_expressions = EXCLUDED.healthy_expressions, metadata = EXCLUDED.metadata;
INSERT INTO public.emotions_encyclopedia (id, emotion_key, arabic_name, category, intensity_level, definition, body_sensations, triggers, healthy_expressions, metadata)
VALUES ('20000000-0000-0000-0000-000000000076', 'depression', 'اكتئاب', 'نفسي / عاطفي / بيولوجي', 2, 'اضطراب مزاجي يتميز بحزن مستمر وفقدان الاهتمام، يؤثر على التفكير، الطاقة، والنشاط اليومي بشكل ملحوظ لأسابيع أو أشهر.', '["تغير في الشهية والنوم؛ أرق أو نوم مستمر :contentReference[oaicite:1]{index=1}","انخفاض الطاقة مع آلام جسدية؛ صداع وأوجاع غير مفسرة :contentReference[oaicite:2]{index=2}","ارتفاع الكورتيزول المزمن → ضعف المناعة ومشاكل صحية :contentReference[oaicite:3]{index=3}"]'::jsonb, '["ضغوط مستمرة أو صدمات نفسية","استعداد جيني وعائلي","خلل في كيمياء الدماغ (مثلاً الدوبامين والسيروتونين)","عزلة اجتماعية أو تغييرات كبيرة في الحياة"]'::jsonb, '[]'::jsonb, '{"english_name":"Depression","type":"أساسي"}'::jsonb)
ON CONFLICT (emotion_key) DO UPDATE SET arabic_name = EXCLUDED.arabic_name, category = EXCLUDED.category, definition = EXCLUDED.definition, body_sensations = EXCLUDED.body_sensations, triggers = EXCLUDED.triggers, healthy_expressions = EXCLUDED.healthy_expressions, metadata = EXCLUDED.metadata;

