INSERT INTO public.psychology_insights (id, insight_text, author_or_source, topic, evidence_level, is_featured)
VALUES ('30000000-0000-0000-0000-000000000001', 'على الرغم من أن أسباب المشاكل قد تكون معقدة للغاية، إلا أن حلولها لا يجب بالضرورة أن تكون كذلك.', 'ستيف دي شازر', 'solution_focused_brief_therapy', 'evidence-based', true)
