INSERT INTO public.psychology_insights (id, insight_text, author_or_source, topic, evidence_level, is_featured)
VALUES ('30000000-0000-0000-0000-000000000002', 'التركيز على ما يريده العميل في حاضره ومستقبله هو حجر الزاوية لحل المشكلات بكفاءة.', 'إنسو كيم بيرج', 'solution_focused_brief_therapy', 'evidence-based', true)
