INSERT INTO public.psychology_insights (id, insight_text, author_or_source, topic, evidence_level, is_featured)
VALUES ('30000000-0000-0000-0000-000000000003', 'بناء الحلول هو عملية لغوية تعاونية بين العميل والمعالج لتطوير وصف تفصيلي للمستقبل المفضل.', 'إليوت كوني', 'solution_focused_brief_therapy', 'evidence-based', true)
