INSERT INTO public.psychology_insights (id, insight_text, author_or_source, topic, evidence_level, is_featured)
VALUES ('30000000-0000-0000-0000-000000000004', 'إذا كان هناك شيء يعمل بنجاح، فافعل منه المزيد، وإذا كان لا يعمل، فلا تكرره وافعل شيئاً مختلفاً.', 'ستيف دي شازر', 'solution_focused_brief_therapy', 'evidence-based', true)
