INSERT INTO public.psychology_insights (id, insight_text, author_or_source, topic, evidence_level, is_featured)
VALUES ('30000000-0000-0000-0000-000000000007', 'في فلسفة SFBT، لا توجد مشكلة تحدث طوال الوقت؛ هناك دائماً ''استثناءات'' تمثل لحظات غياب المشكلة ويمكن البناء عليها للوصول للحل.', 'دليل الوعي النفسي', 'solution_focused_brief_therapy', 'evidence-based', true)
