INSERT INTO public.psychology_insights (id, insight_text, author_or_source, topic, evidence_level, is_featured)
VALUES ('30000000-0000-0000-0000-000000000008', 'يختلف العلاج المركّز على الحلول عن العلاج التقليدي في كونه يتجاوز مرحلة التقييم والتشخيص المفصل للمشاكل ويركز مباشرة على بناء الحلول ومكامن القوة.', 'دليل الوعي النفسي', 'solution_focused_brief_therapy', 'evidence-based', true)
