INSERT INTO public.psychology_insights (id, insight_text, author_or_source, topic, evidence_level, is_featured)
VALUES ('30000000-0000-0000-0000-000000000022', 'راقب ''التغيير قبل الجلسة الأولى'': اسأل نفسك ما هي التحسينات البسيطة التي بدأت تحدث بالفعل في حياتك منذ اللحظة التي قررت فيها طلب المساعدة وحتى الآن؟', 'دليل الوعي النفسي', 'solution_focused_brief_therapy', 'evidence-based', false)
ON CONFLICT (id) DO UPDATE SET insight_text = EXCLUDED.insight_text, author_or_source = EXCLUDED.author_or_source, topic = EXCLUDED.topic, is_featured = EXCLUDED.is_featured;
INSERT INTO public.psychology_insights (id, insight_text, author_or_source, topic, evidence_level, is_featured)
VALUES ('30000000-0000-0000-0000-000000000023', 'عند الشعور بالإحباط واليأس، اسأل نفسك: ''كيف تمكنت من منع الأمور من التدهور والوصول لأسوأ من ذلك؟'' لتكتشف آليات حمايتك وقوتك الكامنة.', 'دليل الوعي النفسي', 'solution_focused_brief_therapy', 'evidence-based', false)
ON CONFLICT (id) DO UPDATE SET insight_text = EXCLUDED.insight_text, author_or_source = EXCLUDED.author_or_source, topic = EXCLUDED.topic, is_featured = EXCLUDED.is_featured;
INSERT INTO public.psychology_insights (id, insight_text, author_or_source, topic, evidence_level, is_featured)
VALUES ('30000000-0000-0000-0000-000000000024', 'طبق ''تقييم المدرج الرقمي'' يومياً: ضع مستوى طاقتك أو ثقتك اليوم على مقياس من 0 إلى 10، ثم اسأل نفسك ما الخطوة البسيطة اللازمة للانتقال درجة واحدة للأعلى؟', 'دليل الوعي النفسي', 'solution_focused_brief_therapy', 'evidence-based', false)
