INSERT INTO public.psychology_insights (id, insight_text, author_or_source, topic, evidence_level, is_featured)
VALUES ('30000000-0000-0000-0000-000000000025', 'ابدأ يومك بالبحث عن الاستثناءات: تذكر يوماً قريباً واجهت فيه نفس الضغوط الحالية لكنك تمكنت من الحفاظ على هدوئك، وكرر نفس التصرفات التي قمت بها حينها.', 'دليل الوعي النفسي', 'solution_focused_brief_therapy', 'evidence-based', false)
