INSERT INTO public.psychology_insights (id, insight_text, author_or_source, topic, evidence_level, is_featured)
VALUES ('30000000-0000-0000-0000-000000000026', 'امتدح جهودك اليومية بوعي: صغ لنفسك عبارات ثناء حقيقية ومحددة حول المهام الصغيرة التي أنجزتها بنجاح لترسيخ شعورك بالكفاءة والتمكن الذاتي.', 'دليل الوعي النفسي', 'solution_focused_brief_therapy', 'evidence-based', false)
