INSERT INTO public.psychology_insights (id, insight_text, author_or_source, topic, evidence_level, is_featured)
VALUES ('30000000-0000-0000-0000-000000000027', 'صمم ''تجارب وأبحاث شخصية ملائمة'': بدلاً من الواجبات المفروضة، جرب إحداث تغيير بسيط جداً في نمط تفاعلك مع الآخرين غداً ولاحظ ردود أفعالهم.', 'دليل الوعي النفسي', 'solution_focused_brief_therapy', 'evidence-based', false)
