INSERT INTO public.psychology_insights (id, insight_text, author_or_source, topic, evidence_level, is_featured)
VALUES ('30000000-0000-0000-0000-000000000028', 'عند حدوث أزمة مفاجئة، توقف للحظة واسأل نفسك: ''ما هو المستقبل المفضل والحل الذي أريد أن أصل إليه الآن؟'' بدلاً من الاستغراق في لوم الذات أو تحليل الأسباب.', 'دليل الوعي النفسي', 'solution_focused_brief_therapy', 'evidence-based', false)
