INSERT INTO public.psychology_insights (id, insight_text, author_or_source, topic, evidence_level, is_featured)
VALUES ('30000000-0000-0000-0000-000000000029', 'دون نجاحاتك الصغيرة باستمرار: احتفظ بقائمة صغيرة للمواقف الصعبة التي تجاوزتها بمرونة لتكون مرجعاً ذهنياً وقوة داعمة لك في أوقات الأزمات.', 'دليل الوعي النفسي', 'solution_focused_brief_therapy', 'evidence-based', false)
