INSERT INTO public.psychology_insights (id, insight_text, author_or_source, topic, evidence_level, is_featured)
VALUES ('30000000-0000-0000-0000-000000000030', 'تحدث بلغة المستقبل والحلول دائماً: استبدل التفكير بـ ''لماذا فشلت؟'' بالتفكير في ''ما الذي سأفعله بشكل مختلف في المرة القادمة للنجاح؟''.', 'دليل الوعي النفسي', 'solution_focused_brief_therapy', 'evidence-based', false)
