INSERT INTO public.psychology_insights (id, insight_text, author_or_source, topic, evidence_level, is_featured)
VALUES ('30000000-0000-0000-0000-000000000031', 'استخدم أسئلة ''ماذا أيضاً؟'' لاستخراج وتوليد خيارات وحلول بديلة إضافية عندما تشعر بأن عقلك قد توقف تماماً عن التفكير الإبداعي.', 'دليل الوعي النفسي', 'solution_focused_brief_therapy', 'evidence-based', false)
