INSERT INTO public.psychology_insights (id, insight_text, author_or_source, topic, evidence_level, is_featured)
VALUES ('30000000-0000-0000-0000-000000000032', 'تجنب التفتيش عن الصراعات الخفية؛ وبدلاً من ذلك ركز انتباهك وجهدك بالكامل على الملاحظات والوقائع السلوكية الملموسة لتغيير واقعك بأسرع وقت.', 'دليل الوعي النفسي', 'solution_focused_brief_therapy', 'evidence-based', false)
