INSERT INTO public.psychology_insights (id, insight_text, author_or_source, topic, evidence_level, is_featured)
VALUES ('30000000-0000-0000-0000-000000000033', 'عند التعرض لضغوط تواصلية، جرب الحفاظ على موقف ''عدم المعرفة المسبقة'' لتستمع للآخرين دون إطلاق أحكام متسرعة أو تصنيف أفعالهم بشكل خاطئ.', 'دليل الوعي النفسي', 'solution_focused_brief_therapy', 'evidence-based', false)
