INSERT INTO public.psychology_insights (id, insight_text, author_or_source, topic, evidence_level, is_featured)
VALUES ('30000000-0000-0000-0000-000000000034', 'كرر السلوكيات التي كانت ناجحة في الماضي؛ فالأدلة تشير إلى أن تكرار ما نجح سابقاً هو الطريق الأكثر أماناً وسرعة لبناء حلول مستدامة.', 'دليل الوعي النفسي', 'solution_focused_brief_therapy', 'evidence-based', false)
