INSERT INTO public.psychology_insights (id, insight_text, author_or_source, topic, evidence_level, is_featured)
VALUES ('30000000-0000-0000-0000-000000000035', 'تحدث بوضوح وثقة مع المقربين منك حول أهدافك الشخصية، وصغ هذه الأهداف في عبارات إيجابية ملموسة تصف ''ما ستفعله'' بدلاً من ''ما ستتوقف عن فعله''.', 'دليل الوعي النفسي', 'solution_focused_brief_therapy', 'evidence-based', false)
