VALUES ('30000000-0000-0000-0000-000000000037', 'اجعل أهدافك اليومية صغيرة ويسيرة وقابلة للقياس، فالتغييرات متناهية الصغر تسهل المتابعة وبناء عادة النجاح اليومي وزيادة دافعيتك.', 'دليل الوعي النفسي', 'solution_focused_brief_therapy', 'evidence-based', false)
