INSERT INTO public.psychology_insights (id, insight_text, author_or_source, topic, evidence_level, is_featured)
VALUES ('30000000-0000-0000-0000-000000000038', 'عند تقييم تواصلك مع شريك حياتك، حدد بدقة الأوقات التي كان فيها التفاهم بينكما رائعاً، وادرس ظروف ذلك التفاهم لإعادتها للواقع مجدداً.', 'دليل الوعي النفسي', 'solution_focused_brief_therapy', 'evidence-based', false)
