INSERT INTO public.psychology_insights (id, insight_text, author_or_source, topic, evidence_level, is_featured)
VALUES ('30000000-0000-0000-0000-000000000039', 'هدف العلاج بالقبول والالتزام ليس التخلص من المشاعر الصعبة، بل التواجد الحقيقي في الحاضر والتحرك نحو عيش قيمنا بصدق وحرية.', 'ستيفن هايز', 'acceptance_commitment_therapy', 'evidence-based', false)
