VALUES ('30000000-0000-0000-0000-000000000041', 'يتيح لنا نموذج Hexaflex فك تشابك صراعاتنا النفسية لنستبدل المعاناة بحياة غنية بالمعنى والحيوية المتوافقة مع أعمق قيمنا الذاتية.', 'نيش نيكوليك', 'acceptance_commitment_therapy', 'evidence-based', false)
