INSERT INTO public.psychology_insights (id, insight_text, author_or_source, topic, evidence_level, is_featured)
VALUES ('30000000-0000-0000-0000-000000000042', 'بدلاً من استهلاك طاقتك في التحكم بالأفكار والمشاعر، ابدأ بـملاحظتها واحتضانها دون صراع لتبدأ التغيير الحقيقي من اللحظة الحالية.', 'روس هاريس', 'acceptance_commitment_therapy', 'evidence-based', false)
