VALUES ('30000000-0000-0000-0000-000000000045', 'اليقظة العقلية في ACT تهدف للاتصال باللحظة الحالية بفضول وانفتاح، مما يضعف آلياً سيطرة الأفكار السلبية والمقلقة عن المستقبل المجهول.', 'دليل الوعي النفسي', 'acceptance_commitment_therapy', 'evidence-based', false)
