VALUES ('30000000-0000-0000-0000-000000000049', 'تشير الأدلة الإمبيريقية إلى أن عدم المرونة النفسية وتجنب المواقف المخيفة يعدان من أهم المتنبئات المباشرة بتطور الاضطرابات النفسية المختلفة.', 'دليل الوعي النفسي', 'acceptance_commitment_therapy', 'evidence-based', false)
