INSERT INTO public.psychology_insights (id, insight_text, author_or_source, topic, evidence_level, is_featured)
VALUES ('30000000-0000-0000-0000-000000000057', 'العيش في اللحظة الحالية والاتصال بالواقع يزيد بشكل علمي من معدلات الرضا والسعادة الشخصية ويقلل من القلق الهدام حول أحداث المستقبل.', 'دليل الوعي النفسي', 'acceptance_commitment_therapy', 'evidence-based', false)
