INSERT INTO public.psychology_insights (id, insight_text, author_or_source, topic, evidence_level, is_featured)
VALUES ('30000000-0000-0000-0000-000000000058', 'أثبتت الأبحاث أن التدريب على قبول الألم وتجنب محاربة الأفكار المزعجة يحسن بشكل واضح من الصحة النفسية العامة للأطفال والمراهقين.', 'دليل الوعي النفسي', 'acceptance_commitment_therapy', 'evidence-based', false)
ON CONFLICT (id) DO UPDATE SET insight_text = EXCLUDED.insight_text, author_or_source = EXCLUDED.author_or_source, topic = EXCLUDED.topic, is_featured = EXCLUDED.is_featured;
INSERT INTO public.psychology_insights (id, insight_text, author_or_source, topic, evidence_level, is_featured)
VALUES ('30000000-0000-0000-0000-000000000059', 'طبق تمرين ''تسمية القصة'': صنف الفكرة السلبية المكررة كقصة مألوفة يعيد عقلك عرضها دائماً، مثل: ''ها هي قصة أنا لست كافياً تبدأ مجدداً''.', 'دليل الوعي النفسي', 'acceptance_commitment_therapy', 'evidence-based', false)
ON CONFLICT (id) DO UPDATE SET insight_text = EXCLUDED.insight_text, author_or_source = EXCLUDED.author_or_source, topic = EXCLUDED.topic, is_featured = EXCLUDED.is_featured;
INSERT INTO public.psychology_insights (id, insight_text, author_or_source, topic, evidence_level, is_featured)
VALUES ('30000000-0000-0000-0000-000000000060', 'كرر فكرتك المقلقة بصوت سخيف أو كرتوني مضحك، أو قم بغنائها، لثوانٍ معدودة؛ ستجد أن الكلمات فقدت جديتها وسطوتها المخيفة على مشاعرك.', 'دليل الوعي النفسي', 'acceptance_commitment_therapy', 'evidence-based', false)
ON CONFLICT (id) DO UPDATE SET insight_text = EXCLUDED.insight_text, author_or_source = EXCLUDED.author_or_source, topic = EXCLUDED.topic, is_featured = EXCLUDED.is_featured;
INSERT INTO public.psychology_insights (id, insight_text, author_or_source, topic, evidence_level, is_featured)
VALUES ('30000000-0000-0000-0000-000000000061', 'قل لعقلك بلطف: ''شكراً لك يا عقلي على هذه الفكرة، وشكراً لمحاولتك حمايتي''، مما يفصلك عن التماهي والصراع العنيف مع الفكرة المزعجة.', 'دليل الوعي النفسي', 'acceptance_commitment_therapy', 'evidence-based', false)
ON CONFLICT (id) DO UPDATE SET insight_text = EXCLUDED.insight_text, author_or_source = EXCLUDED.author_or_source, topic = EXCLUDED.topic, is_featured = EXCLUDED.is_featured;
INSERT INTO public.psychology_insights (id, insight_text, author_or_source, topic, evidence_level, is_featured)
VALUES ('30000000-0000-0000-0000-000000000062', 'اكتب فكرتك المزعجة على ورقة صغيرة، واحملها معك في جيبك طوال اليوم كطريقة ملموسة للتعايش مع وجودها والتركيز على أفعالك الهامة.', 'دليل الوعي النفسي', 'acceptance_commitment_therapy', 'evidence-based', false)
ON CONFLICT (id) DO UPDATE SET insight_text = EXCLUDED.insight_text, author_or_source = EXCLUDED.author_or_source, topic = EXCLUDED.topic, is_featured = EXCLUDED.is_featured;
INSERT INTO public.psychology_insights (id, insight_text, author_or_source, topic, evidence_level, is_featured)
VALUES ('30000000-0000-0000-0000-000000000063', 'طبق تمرين ''المرساة في العاصفة'': عندما تجتاحك مشاعر حادة، اشعر بملامسة قدميك للأرض تماماً، وركز على حواسك الخمس لتعود للواقع الحالي.', 'دليل الوعي النفسي', 'acceptance_commitment_therapy', 'evidence-based', false)
ON CONFLICT (id) DO UPDATE SET insight_text = EXCLUDED.insight_text, author_or_source = EXCLUDED.author_or_source, topic = EXCLUDED.topic, is_featured = EXCLUDED.is_featured;
INSERT INTO public.psychology_insights (id, insight_text, author_or_source, topic, evidence_level, is_featured)
VALUES ('30000000-0000-0000-0000-000000000064', 'استخدم استعارة ''الأوراق على المجرى المائي'': تخيل أفكارك المقلقة كأوراق شجر تتساقط فوق مجرى ماء جارٍ، وشاهدها وهي تمر وتتلاشى ببطء ولطف.', 'دليل الوعي النفسي', 'acceptance_commitment_therapy', 'evidence-based', false)
ON CONFLICT (id) DO UPDATE SET insight_text = EXCLUDED.insight_text, author_or_source = EXCLUDED.author_or_source, topic = EXCLUDED.topic, is_featured = EXCLUDED.is_featured;
INSERT INTO public.psychology_insights (id, insight_text, author_or_source, topic, evidence_level, is_featured)
VALUES ('30000000-0000-0000-0000-000000000065', 'تخيل أفكارك الغاضبة كغيوم عابرة في سماء زرقاء واسعة؛ أنت لست الغيوم المقلقة، أنت السماء الفسيحة التي تراقب مرورها بسلام وصبر.', 'دليل الوعي النفسي', 'acceptance_commitment_therapy', 'evidence-based', false)
ON CONFLICT (id) DO UPDATE SET insight_text = EXCLUDED.insight_text, author_or_source = EXCLUDED.author_or_source, topic = EXCLUDED.topic, is_featured = EXCLUDED.is_featured;
INSERT INTO public.psychology_insights (id, insight_text, author_or_source, topic, evidence_level, is_featured)
VALUES ('30000000-0000-0000-0000-000000000066', 'طبق تمرين ''الرماية بالبوصلة'' لتحديد قيمك الذاتية بدقة في مجالات العلاقات، والعمل، والصحة، والترفيه، وتأكد من السير باتجاهها يومياً.', 'دليل الوعي النفسي', 'acceptance_commitment_therapy', 'evidence-based', false)
ON CONFLICT (id) DO UPDATE SET insight_text = EXCLUDED.insight_text, author_or_source = EXCLUDED.author_or_source, topic = EXCLUDED.topic, is_featured = EXCLUDED.is_featured;
INSERT INTO public.psychology_insights (id, insight_text, author_or_source, topic, evidence_level, is_featured)
VALUES ('30000000-0000-0000-0000-000000000067', 'اسأل نفسك دائماً: ''إذا كان التوتر غائباً تماماً، ما السلوك الإيجابي والنبيل الذي كنت سأبدأ في ممارسته فوراً؟'' لتكتشف قيمك الحقيقية.', 'دليل الوعي النفسي', 'acceptance_commitment_therapy', 'evidence-based', false)
ON CONFLICT (id) DO UPDATE SET insight_text = EXCLUDED.insight_text, author_or_source = EXCLUDED.author_or_source, topic = EXCLUDED.topic, is_featured = EXCLUDED.is_featured;
INSERT INTO public.psychology_insights (id, insight_text, author_or_source, topic, evidence_level, is_featured)
VALUES ('30000000-0000-0000-0000-000000000068', 'افسح مجالاً واسعاً لمشاعرك الصعبة: بدلاً من كبت القلق، تنفس بعمق واشعر به كطاقة جسدية دون محاولة طردها أو مقاومتها بعنف.', 'دليل الوعي النفسي', 'acceptance_commitment_therapy', 'evidence-based', false)
ON CONFLICT (id) DO UPDATE SET insight_text = EXCLUDED.insight_text, author_or_source = EXCLUDED.author_or_source, topic = EXCLUDED.topic, is_featured = EXCLUDED.is_featured;
INSERT INTO public.psychology_insights (id, insight_text, author_or_source, topic, evidence_level, is_featured)
VALUES ('30000000-0000-0000-0000-000000000069', 'راقب الأنماط اللفظية التي تصيغ بها أفكارك: تجنب قول ''أنا حزين دائماً'' واستبدلها بـ ''أنا ألاحظ أن لدي مشاعر حزن حالياً عابرة''.', 'دليل الوعي النفسي', 'acceptance_commitment_therapy', 'evidence-based', false)
ON CONFLICT (id) DO UPDATE SET insight_text = EXCLUDED.insight_text, author_or_source = EXCLUDED.author_or_source, topic = EXCLUDED.topic, is_featured = EXCLUDED.is_featured;
INSERT INTO public.psychology_insights (id, insight_text, author_or_source, topic, evidence_level, is_featured)
VALUES ('30000000-0000-0000-0000-000000000070', 'ضع خطة عمل ملتزمة أسبوعياً: حدد قيمتين أساسيتين تود عيشهما، واكتب فعلين ملموسين وبسيطين ستلتزم بتأديتهما بمسؤولية لدعم قيمك.', 'دليل الوعي النفسي', 'acceptance_commitment_therapy', 'evidence-based', false)
ON CONFLICT (id) DO UPDATE SET insight_text = EXCLUDED.insight_text, author_or_source = EXCLUDED.author_or_source, topic = EXCLUDED.topic, is_featured = EXCLUDED.is_featured;
INSERT INTO public.psychology_insights (id, insight_text, author_or_source, topic, evidence_level, is_featured)
VALUES ('30000000-0000-0000-0000-000000000071', 'عند شعورك بالعجز عن اتخاذ القرارات، ارجع لقيمك الحاكمة: تذكر ما يمنح حياتك معنى وقم بتأدية أصغر فعل ممكن يتماشى مع تلك القيم.', 'دليل الوعي النفسي', 'acceptance_commitment_therapy', 'evidence-based', false)
ON CONFLICT (id) DO UPDATE SET insight_text = EXCLUDED.insight_text, author_or_source = EXCLUDED.author_or_source, topic = EXCLUDED.topic, is_featured = EXCLUDED.is_featured;
INSERT INTO public.psychology_insights (id, insight_text, author_or_source, topic, evidence_level, is_featured)
VALUES ('30000000-0000-0000-0000-000000000072', 'عند تذكر صدمات الماضي، ذكّر نفسك أنك الآن في الحاضر بسلام؛ ركز انتباهك بالكامل على محيطك المادي الحالي عبر الحواس الخمس لحماية اتزانك.', 'دليل الوعي النفسي', 'acceptance_commitment_therapy', 'evidence-based', false)
ON CONFLICT (id) DO UPDATE SET insight_text = EXCLUDED.insight_text, author_or_source = EXCLUDED.author_or_source, topic = EXCLUDED.topic, is_featured = EXCLUDED.is_featured;
INSERT INTO public.psychology_insights (id, insight_text, author_or_source, topic, evidence_level, is_featured)
VALUES ('30000000-0000-0000-0000-000000000073', 'ميز بين أفكارك كافتراضات عقلية وبين الحقائق المادية المطلقة؛ فالعقل يحب صياغة التحذيرات الكارثية لكنها نادراً ما تعبر عن الواقع بدقة.', 'دليل الوعي النفسي', 'acceptance_commitment_therapy', 'evidence-based', false)
