INSERT INTO public.psychology_insights (id, insight_text, author_or_source, topic, evidence_level, is_featured)
VALUES ('30000000-0000-0000-0000-000000000074', 'تجنب الركض خلف فكرة ''أنا لست جيداً كفاية''؛ وبدلاً من تصديقها، راقبها واعتبرها مجرد رأي قديم وغير مفيد يصيغه عقلك المجهد.', 'دليل الوعي النفسي', 'acceptance_commitment_therapy', 'evidence-based', false)
ON CONFLICT (id) DO UPDATE SET insight_text = EXCLUDED.insight_text, author_or_source = EXCLUDED.author_or_source, topic = EXCLUDED.topic, is_featured = EXCLUDED.is_featured;
INSERT INTO public.psychology_insights (id, insight_text, author_or_source, topic, evidence_level, is_featured)
VALUES ('30000000-0000-0000-0000-000000000075', 'عند التعرض لنوبة توتر حادة، جرب الجلوس لـ 5 دقائق والتركيز بالكامل على ملمس وشكل وحجم غرض مادي بسيط كقلم أو كوب لتهدئة جهازك العصبي.', 'دليل الوعي النفسي', 'acceptance_commitment_therapy', 'evidence-based', false)
ON CONFLICT (id) DO UPDATE SET insight_text = EXCLUDED.insight_text, author_or_source = EXCLUDED.author_or_source, topic = EXCLUDED.topic, is_featured = EXCLUDED.is_featured;
INSERT INTO public.psychology_insights (id, insight_text, author_or_source, topic, evidence_level, is_featured)
VALUES ('30000000-0000-0000-0000-000000000076', 'لا تدع مشاعرك تقود أفعالك بالكامل؛ فالتعايش المقبول مع مشاعر الخوف العابرة يتيح لك المبادرة وتأدية أفعال شجاعة ومهمة في حياتك وعلاقاتك.', 'دليل الوعي النفسي', 'acceptance_commitment_therapy', 'evidence-based', false)
ON CONFLICT (id) DO UPDATE SET insight_text = EXCLUDED.insight_text, author_or_source = EXCLUDED.author_or_source, topic = EXCLUDED.topic, is_featured = EXCLUDED.is_featured;
INSERT INTO public.psychology_insights (id, insight_text, author_or_source, topic, evidence_level, is_featured)
VALUES ('30000000-0000-0000-0000-000000000077', 'الجدلية هي القدرة المتوازنة على الجمع بين فكرتين تبدوان متناقضتين تماماً في الظاهر: القبول الكامل للذات، والتغيير المستمر للسلوك.', 'مارشا لينهان', 'dialectical_behavior_therapy', 'evidence-based', false)
