INSERT INTO public.psychology_insights (id, insight_text, author_or_source, topic, evidence_level, is_featured)
VALUES ('30000000-0000-0000-0000-000000000078', 'إن اليقظة الذهنية والوعي باللحظة هما الأساس المتين الذي تبنى عليه كافة مهارات التحمل والتأقلم وتنظيم الانفعالات الأخرى.', 'لين بيدرسون', 'dialectical_behavior_therapy', 'evidence-based', false)
