INSERT INTO public.psychology_insights (id, insight_text, author_or_source, topic, evidence_level, is_featured)
VALUES ('30000000-0000-0000-0000-000000000079', 'جوهر مهارات DBT ليس إلغاء مشاعرنا أو الهروب من عواطفنا، وإنما تعلم كيفية العيش معها بأمان دون أن تترجم لسلوك مدمر.', 'دكتور محمد حجازي', 'dialectical_behavior_therapy', 'evidence-based', false)
