INSERT INTO public.psychology_insights (id, insight_text, author_or_source, topic, evidence_level, is_featured)
VALUES ('30000000-0000-0000-0000-000000000080', 'التركيز على ممارسات اليقظة والاتصال بالحاضر يفتح أبواب الحكمة والاتزان النفسي ويساعد على خفض أعراض الاكتئاب والتوتر.', 'مروة مصلحي', 'dialectical_behavior_therapy', 'evidence-based', false)
