INSERT INTO public.psychology_insights (id, insight_text, author_or_source, topic, evidence_level, is_featured)
VALUES ('30000000-0000-0000-0000-000000000081', 'توضح النظرية البيولوجية الاجتماعية أن الأفراد المعرضين لاضطراب الشخصية الحدية يمتلكون حساسية فسيولوجية عالية واستجابة عاطفية شديدة للألم.', 'دليل الوعي النفسي', 'dialectical_behavior_therapy', 'evidence-based', false)
