INSERT INTO public.psychology_insights (id, insight_text, author_or_source, topic, evidence_level, is_featured)
VALUES ('30000000-0000-0000-0000-000000000082', 'البيئة غير الصالحة عاطفياً (Invalidating Environment) التي تتجاهل مشاعر الطفل أو تسخر منها تعد ركيزة لتطوير صعوبات مزمنة في تنظيم الانفعال عند البلوغ.', 'دليل الوعي النفسي', 'dialectical_behavior_therapy', 'evidence-based', false)
