INSERT INTO public.psychology_insights (id, insight_text, author_or_source, topic, evidence_level, is_featured)
VALUES ('30000000-0000-0000-0000-000000000083', 'العقل الحكيم (Wise Mind) هو التركيب والدمج المتوازن بين العقل المنطقي البارد والعقل العاطفي المشحون بالانفعالات للوصول لقرارات حكيمة.', 'دليل الوعي النفسي', 'dialectical_behavior_therapy', 'evidence-based', false)
