INSERT INTO public.psychology_insights (id, insight_text, author_or_source, topic, evidence_level, is_featured)
VALUES ('30000000-0000-0000-0000-000000000084', 'أثبتت التجارب الإكلينيكية المضبوطة أن التدريب الجماعي على مهارات DBT كتدخل مستقل يقلل بشكل ملموس من السلوكيات المؤذية للذات ونسب دخول المستشفى.', 'دليل الوعي النفسي', 'dialectical_behavior_therapy', 'evidence-based', false)
