VALUES ('30000000-0000-0000-0000-000000000110', 'عند شعورك بالغرق في زحام الأفكار، خذ خطوة للوراء وتنفس بعمق، ودع أفكارك تعبر بسلام دون صراع أو تصديق أعمى لمحتواها الكارثي.', 'دليل الوعي النفسي', 'dialectical_behavior_therapy', 'evidence-based', false)
