VALUES ('30000000-0000-0000-0000-000000000112', 'عند مواجهة المشاعر الحادة، ميز بوضوح بين العواطف الجسدية العابرة وبين الواقع المادي الحقيقي لتمنع تحول الانفعالات إلى أزمات مدمرة.', 'دليل الوعي النفسي', 'dialectical_behavior_therapy', 'evidence-based', false)
