VALUES ('30000000-0000-0000-0000-000000000113', 'شارك بكامل وجودك وانتباهك في نشاطك الحالي: سواء كنت تتناول وجبة أو تغسل يديك، ركز تماماً على تفاصيل اللحظة لتعزز وعيك واستقرارك.', 'دليل الوعي النفسي', 'dialectical_behavior_therapy', 'evidence-based', false)
