INSERT INTO public.psychology_insights (id, insight_text, author_or_source, topic, evidence_level, is_featured)
VALUES ('30000000-0000-0000-0000-000000000115', 'العلاج هو مساحة تتيح رفع الكبت، وكشف الدوافع والدفاعات اللاشعورية، والتعبير الحر عن الانفعالات العميقة للتغيير الذاتي.', 'سيغموند فرويد', 'psychodynamic_therapy', 'evidence-based', false)
