INSERT INTO public.psychology_insights (id, insight_text, author_or_source, topic, evidence_level, is_featured)
VALUES ('30000000-0000-0000-0000-000000000116', 'المنظور الديناميكي الحديث هو من أكثر المدارس شمولاً واتساعاً، كونه يمس الشخصية، التطور الإنساني، والاضطرابات معاً بمرونة وعمق.', 'راسل فولمر', 'psychodynamic_therapy', 'evidence-based', false)
