INSERT INTO public.psychology_insights (id, insight_text, author_or_source, topic, evidence_level, is_featured)
VALUES ('30000000-0000-0000-0000-000000000117', 'إن إدراكنا لآليات الدفاع النفسي اللاشعورية وتطوير الاستبصار الذاتي هما المفتاحان لتجاوز صراعات الماضي والتحرر في الحاضر.', 'نانسي ماكويليامز', 'psychodynamic_therapy', 'evidence-based', false)
