INSERT INTO public.psychology_insights (id, insight_text, author_or_source, topic, evidence_level, is_featured)
VALUES ('30000000-0000-0000-0000-000000000118', 'العمليات اللاشعورية تتدخل في صياغة سلوكياتنا اليومية وقراراتنا الشخصية بشكل دائم وبأكثر مما يظن عقلنا الواعي بكثير.', 'روبرت بورنشتاين', 'psychodynamic_therapy', 'evidence-based', false)
