INSERT INTO public.psychology_insights (id, insight_text, author_or_source, topic, evidence_level, is_featured)
VALUES ('30000000-0000-0000-0000-000000000119', 'يفترض العلاج النفسي الديناميكي الحديث أن السلوكيات الصعبة والأعراض النفسية الحالية تنبع دائماً من صراعات لا شعورية وتجارب مبكرة غير محلولة.', 'دليل الوعي النفسي', 'psychodynamic_therapy', 'evidence-based', false)
ON CONFLICT (id) DO UPDATE SET insight_text = EXCLUDED.insight_text, author_or_source = EXCLUDED.author_or_source, topic = EXCLUDED.topic, is_featured = EXCLUDED.is_featured;
INSERT INTO public.psychology_insights (id, insight_text, author_or_source, topic, evidence_level, is_featured)
VALUES ('30000000-0000-0000-0000-000000000120', 'التجارب والعلاقات المبكرة مع الوالدين في مرحلة الطفولة تشكل ''مخططات'' داخلية لا شعورية توجه توقعات الفرد وطريقة تواصله في علاقاته اللاحقة.', 'دليل الوعي النفسي', 'psychodynamic_therapy', 'evidence-based', false)
ON CONFLICT (id) DO UPDATE SET insight_text = EXCLUDED.insight_text, author_or_source = EXCLUDED.author_or_source, topic = EXCLUDED.topic, is_featured = EXCLUDED.is_featured;
INSERT INTO public.psychology_insights (id, insight_text, author_or_source, topic, evidence_level, is_featured)
VALUES ('30000000-0000-0000-0000-000000000121', 'مبدأ الحتمية النفسية (Psychic Causality) يفترض أن كل فكرة أو شعور أو حلم لا يحدث بمحض الصدفة، بل له دلالة وأسباب لا شعورية عميقة.', 'دليل الوعي النفسي', 'psychodynamic_therapy', 'evidence-based', false)
ON CONFLICT (id) DO UPDATE SET insight_text = EXCLUDED.insight_text, author_or_source = EXCLUDED.author_or_source, topic = EXCLUDED.topic, is_featured = EXCLUDED.is_featured;
INSERT INTO public.psychology_insights (id, insight_text, author_or_source, topic, evidence_level, is_featured)
VALUES ('30000000-0000-0000-0000-000000000122', 'آليات الدفاع النفسي هي استراتيجيات لا شعورية يلجأ إليها العقل لحماية الذات من القلق والتوتر الحاد المصاحب للصراعات النفسية.', 'دليل الوعي النفسي', 'psychodynamic_therapy', 'evidence-based', false)
ON CONFLICT (id) DO UPDATE SET insight_text = EXCLUDED.insight_text, author_or_source = EXCLUDED.author_or_source, topic = EXCLUDED.topic, is_featured = EXCLUDED.is_featured;
INSERT INTO public.psychology_insights (id, insight_text, author_or_source, topic, evidence_level, is_featured)
VALUES ('30000000-0000-0000-0000-000000000123', 'هناك تدرج في نضج آليات الدفاع؛ فالكبت والإنكار آليات غير ناضجة قد تضر بالصحة، بينما التسامي والعقلنة يمثلان آليات ناضجة وفعالة وصحية.', 'دليل الوعي النفسي', 'psychodynamic_therapy', 'evidence-based', false)
ON CONFLICT (id) DO UPDATE SET insight_text = EXCLUDED.insight_text, author_or_source = EXCLUDED.author_or_source, topic = EXCLUDED.topic, is_featured = EXCLUDED.is_featured;
INSERT INTO public.psychology_insights (id, insight_text, author_or_source, topic, evidence_level, is_featured)
VALUES ('30000000-0000-0000-0000-000000000124', 'التحويل (Transference) هو إعادة تمثيل لا شعورية لأنماط العلاقات القديمة وإسقاط مشاعر الماضي على المعالج أو الآخرين في الحاضر بغير وعي.', 'دليل الوعي النفسي', 'psychodynamic_therapy', 'evidence-based', false)
