-- 5. STANDALONE SCIENTIFIC ARTICLES
INSERT INTO public.content (id, slug, language, title, description, content_type, status, markdown_content, featured_image, metadata, published_at)
VALUES ('55555555-5555-5555-5555-555555555551', 'thinking-errors', 'ar', 'التشوهات المعرفية (Thinking Errors)', 'دليل إكلينيكي مفصل للتعرف على أنماط التفكير التلقائية المشوهة وكيفية تفنيدها وتعديلها وفق أساليب العلاج المعرفي السلوكي (CBT).', 'scientific_page', 'published', '# دليل التشوهات المعرفية (Cognitive Distortions)

التشوهات المعرفية هي أنماط تفكير تلقائية غير عقلانية تجعلنا نرى الواقع بصورة مشوهة أو متطرفة. تحدث هذه الأفكار في أجزاء من الثانية وتؤدي مباشرة إلى مشاعر سلبية حادة مثل القلق، الحزن، الذنب، أو الإحباط.

:::note
**ملاحظة إكلينيكية:**
الهدف من رصد التشوهات المعرفية ليس منع الأفكار من الظهور، بل التراجع خطوة للخلف وملاحظتها كأفكار عابرة وليست حقائق قاطعة.
:::

## 1. التفكير بالأبيض والأسود (All-or-Nothing Thinking)
رؤية الأمور في قطبين متطرفين دون أي مساحات رمادية: إما نجاح تام أو فشل ذريع.

## 2. التعميم المفرط (Overgeneralization)
اعتبار تجربة سلبية واحدة دليلاً قاطعاً على نمط دائم في الحياة باستخدام كلمات مثل "دائماً" أو "أبداً".

## 3. التصفية الذهنية (Mental Filter)
التركيز على تفصيلة سلبية واحدة وتجاهل كل ما هو إيجابي في الموقف.

## 4. القفز إلى الاستنتاجات (Jumping to Conclusions)
* **قراءة الأفكار (Mind Reading):** افتراض معرفة ما يفكر فيه الآخرون بسوء ظن.
* **التنبؤ الكارثي (Fortune Telling):** توقع حدوث أسوأ السيناريوهات والتصرف كأنها حتمية.', '/article-by3DYy7JylaR.webp', '{"reading_time_minutes":7,"framework":"CBT"}'::jsonb, NOW())
ON CONFLICT (slug, language) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, markdown_content = EXCLUDED.markdown_content, featured_image = EXCLUDED.featured_image, metadata = EXCLUDED.metadata;
